('article', '2002', 'published', '{"id":"2002","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-28T05:30:00Z","hue":340,"personIds":["anitta","bad-bunny","j-balvin","shakira"],"sources":[{"name":"POPline","url":"https://portalpopline.com.br/anitta-perde-vma-bad-bunny-mantem-recorde/"},{"name":"CNN Brasil","url":"https://www.cnnbrasil.com.br/pop/musica/vma-2026-anitta-perde-premio-de-melhor-latino-para-bad-bunny/"},{"name":"Exame","url":"https://exame.com/pop/anitta-no-vma-2026-choka-choka-disputa-melhor-musica-latina-com-bad-bunny-karol-g-e-rosalia/"}],"t":{"pt":{"slug":"anitta-perde-vma-melhor-latino-bad-bunny","headline":"Anitta perde Melhor Latino no VMA para Bad Bunny, mas segue empatada no recorde da categoria","summary":"Com “Choka Choka”, parceria com Shakira, a brasileira concorria ao quarto troféu; Bad Bunny venceu com “NUEVAYoL”.","body":["Anitta não levou o prêmio de Melhor Clipe Latino no VMA 2026. A categoria ficou com Bad Bunny, por “NUEVAYoL”. A brasileira concorria com “Choka Choka”, sua primeira parceria com Shakira, lançada em abril.","Foi a primeira derrota de Anitta na categoria, que ela havia vencido em 2022, 2023 e 2024. Com os três troféus, ela continua empatada com J Balvin como maior vencedora de Melhor Latino na história da premiação.","A cantora não esteve na cerimônia em Los Angeles. Segundo o POPline, ela viajou para a Europa depois de encerrar compromissos com a TV Globo."]},"en":{"slug":"anitta-loses-vma-best-latin-bad-bunny","headline":"Anitta loses Best Latin at the VMAs to Bad Bunny but keeps a share of the category record","summary":"The Brazilian star was up for a fourth win with “Choka Choka”, her collab with Shakira; Bad Bunny won with “NUEVAYoL”.","body":["Anitta did not win Best Latin at the 2026 VMAs. The award went to Bad Bunny for “NUEVAYoL”. Anitta was nominated for “Choka Choka”, her first collaboration with Shakira, released in April.","It was her first loss in the category, which she won in 2022, 2023 and 2024. With three trophies, she remains tied with J Balvin as the most awarded artist in Best Latin history.","She did not attend the ceremony in Los Angeles. According to POPline, she traveled to Europe after wrapping commitments with TV Globo."]},"es":{"slug":"anitta-pierde-vma-mejor-latino-bad-bunny","headline":"Anitta pierde Mejor Latino en los VMA ante Bad Bunny, pero sigue empatada en el récord de la categoría","summary":"La brasileña buscaba su cuarto trofeo con “Choka Choka”, junto a Shakira; Bad Bunny ganó con “NUEVAYoL”.","body":["Anitta no ganó Mejor Video Latino en los VMA 2026. El premio fue para Bad Bunny por “NUEVAYoL”. La brasileña competía con “Choka Choka”, su primera colaboración con Shakira, lanzada en abril.","Fue su primera derrota en la categoría, que había ganado en 2022, 2023 y 2024. Con tres trofeos, sigue empatada con J Balvin como la artista más premiada de Mejor Latino.","No asistió a la gala en Los Ángeles. Según POPline, viajó a Europa tras terminar sus compromisos con TV Globo."]}}}'::jsonb),
('article', '2001', 'published', '{"id":"2001","section":"news","confidence":"confirmed","risk":"green","breaking":true,"publishedAt":"2026-09-28T04:10:00Z","hue":330,"personIds":["taylor-swift","madonna","bts","lisa","sabrina-carpenter","charli-xcx"],"sources":[{"name":"Billboard Brasil","url":"https://billboard.com.br/vma-2026-vencedores-premiacao/"},{"name":"Variety","url":"https://variety.com/2026/music/news/vmas-winners-list-mtv-awards-2026-show-1236876862/"},{"name":"Deadline","url":"https://deadline.com/2026/09/mtv-vmas-2026-winners-list-1237115040/"}],"factBox":{"pt":{"known":["Clipe do Ano: Taylor Swift, “The Fate of Ophelia”","Artista do Ano: Madonna, que levou 7 troféus","Música do Ano: BTS, “Swim”","Artista Revelação: Sienna Spiro"],"unknown":[]},"en":{"known":["Video of the Year: Taylor Swift, “The Fate of Ophelia”","Artist of the Year: Madonna, who took home 7 trophies","Song of the Year: BTS, “Swim”","Best New Artist: Sienna Spiro"],"unknown":[]},"es":{"known":["Video del Año: Taylor Swift, “The Fate of Ophelia”","Artista del Año: Madonna, que se llevó 7 trofeos","Canción del Año: BTS, “Swim”","Artista Revelación: Sienna Spiro"],"unknown":[]}},"t":{"pt":{"slug":"vma-2026-vencedores-taylor-swift-madonna","headline":"VMA 2026: Taylor Swift leva Clipe do Ano e Madonna sai com sete troféus","summary":"Na noite de domingo em Los Angeles, Madonna foi eleita Artista do Ano e o BTS venceu Música do Ano com “Swim”.","body":["O MTV Video Music Awards 2026 aconteceu no domingo (27), em Los Angeles, e teve Taylor Swift como vencedora de Clipe do Ano com “The Fate of Ophelia”. Ela também levou Melhor Direção por “Opalite”.","A grande campeã da noite, porém, foi Madonna. Com 11 indicações, o maior número da carreira, ela conquistou sete prêmios, incluindo Artista do Ano e Melhor Colaboração com Sabrina Carpenter por “Bring Your Love”. A cantora abriu a cerimônia ao lado de Charli xcx e Sabrina, em sua primeira apresentação no VMA em 23 anos.","O BTS venceu Música do Ano e Melhor K-pop com “Swim”, Lisa ganhou Melhor Pop com “Dream” e Sienna Spiro foi eleita Artista Revelação. O Nirvana recebeu o prêmio Video Vanguard."]},"en":{"slug":"vmas-2026-winners-taylor-swift-madonna","headline":"VMAs 2026: Taylor Swift wins Video of the Year as Madonna takes home seven trophies","summary":"At Sunday’s show in Los Angeles, Madonna was named Artist of the Year and BTS won Song of the Year with “Swim”.","body":["The 2026 MTV Video Music Awards took place Sunday in Los Angeles, with Taylor Swift winning Video of the Year for “The Fate of Ophelia”. She also picked up Best Direction for “Opalite”.","The night belonged to Madonna. With 11 nominations, the most of her career, she won seven awards, including Artist of the Year and Best Collaboration with Sabrina Carpenter for “Bring Your Love”. She opened the show alongside Charli xcx and Carpenter in her first VMAs performance in 23 years.","BTS won Song of the Year and Best K-Pop for “Swim”, Lisa took Best Pop for “Dream” and Sienna Spiro was named Best New Artist. Nirvana received the Video Vanguard Award."]},"es":{"slug":"vma-2026-ganadores-taylor-swift-madonna","headline":"VMA 2026: Taylor Swift gana Video del Año y Madonna se lleva siete trofeos","summary":"En la gala del domingo en Los Ángeles, Madonna fue elegida Artista del Año y BTS ganó Canción del Año con “Swim”.","body":["Los MTV Video Music Awards 2026 se celebraron el domingo en Los Ángeles, con Taylor Swift ganando Video del Año por “The Fate of Ophelia”. También se llevó Mejor Dirección por “Opalite”.","La gran ganadora, sin embargo, fue Madonna. Con 11 nominaciones, su máximo histórico, obtuvo siete premios, entre ellos Artista del Año y Mejor Colaboración con Sabrina Carpenter por “Bring Your Love”. Abrió la gala junto a Charli xcx y Sabrina, en su primera actuación en los VMA en 23 años.","BTS ganó Canción del Año y Mejor K-pop con “Swim”, Lisa se llevó Mejor Pop con “Dream” y Sienna Spiro fue elegida Artista Revelación. Nirvana recibió el premio Video Vanguard."]}}}'::jsonb),
('article', '2010', 'published', '{"id":"2010","section":"movies-tv","confidence":"confirmed","risk":"green","publishedAt":"2026-09-27T18:00:00Z","hue":0,"personIds":[],"sources":[{"name":"Metrópoles","url":"https://www.metropoles.com/entretenimento/netflix-divulga-lancamentos-de-outubro-veja-a-lista-completa"}],"t":{"pt":{"slug":"netflix-lancamentos-outubro-2026","headline":"Netflix em outubro: “A Leste do Éden”, nova parte de “Lupin” e maratona de terror","summary":"O mês tem série com Florence Pugh, “Pecadores”, “Anora” e um documentário sobre Matthew Perry.","body":["A Netflix abre outubro com “A Leste do Éden”, série original estrelada por Florence Pugh, que estreia no dia 1º. No dia 23 chega a quarta parte de “Lupin”, com Assane recomeçando a vida após quatro anos preso.","Entre os filmes, os destaques são “Pecadores”, com Michael B. Jordan (4/10), e “Anora” (23/10). Para o Halloween, o catálogo recebe “Nosferatu” (2/10), os filmes da franquia “Pânico” (9/10) e “Um Lugar Silencioso” 1 e 2 (15/10).","No dia 27 estreia um documentário sobre a vida de Matthew Perry."]},"en":{"slug":"netflix-new-releases-october-2026","headline":"Netflix in October: “East of Eden”, a new “Lupin” part and a horror lineup","summary":"The month brings a Florence Pugh series, “Sinners”, “Anora” and a documentary about Matthew Perry.","body":["Netflix opens October with “East of Eden”, an original series starring Florence Pugh, on the 1st. Part 4 of “Lupin” arrives on the 23rd, with Assane starting over after four years in prison.","On the film side, highlights include “Sinners” with Michael B. Jordan (Oct 4) and “Anora” (Oct 23). For Halloween, the catalog adds “Nosferatu” (Oct 2), the “Scream” films (Oct 9) and “A Quiet Place” parts 1 and 2 (Oct 15).","A documentary about Matthew Perry’s life premieres on October 27."]},"es":{"slug":"netflix-estrenos-octubre-2026","headline":"Netflix en octubre: “Al este del Edén”, nueva parte de “Lupin” y maratón de terror","summary":"El mes trae una serie con Florence Pugh, “Pecadores”, “Anora” y un documental sobre Matthew Perry.","body":["Netflix abre octubre con “Al este del Edén”, serie original protagonizada por Florence Pugh, el día 1. El 23 llega la cuarta parte de “Lupin”, con Assane empezando de cero tras cuatro años preso.","En cine destacan “Pecadores”, con Michael B. Jordan (4/10), y “Anora” (23/10). Para Halloween llegan “Nosferatu” (2/10), las películas de “Scream” (9/10) y “Un lugar en silencio” 1 y 2 (15/10).","El 27 se estrena un documental sobre la vida de Matthew Perry."]}}}'::jsonb),
('article', '2008', 'published', '{"id":"2008","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-09-27T12:00:00Z","hue":200,"personIds":["zayn","robbie-williams","bts","hayley-williams","ca7riel-paco-amoroso","ed-sheeran","anitta"],"sources":[{"name":"Exame","url":"https://exame.com/pop/veja-o-calendario-de-shows-internacionais-no-brasil-ate-o-final-de-2026/"}],"t":{"pt":{"slug":"agenda-shows-internacionais-brasil-fim-de-2026","headline":"De ZAYN a Ed Sheeran: os shows internacionais que ainda passam pelo Brasil em 2026","summary":"Outubro abre com ZAYN e Robbie Williams; BTS, Hayley Williams e CA7RIEL & Paco Amoroso vêm em seguida, e Ed Sheeran fecha o ano.","body":["O último trimestre de 2026 tem agenda cheia de shows internacionais. ZAYN abre a sequência em 10 de outubro, no Nubank Parque, em São Paulo, e Robbie Williams toca no mesmo local em 13 de outubro, sua volta ao país depois de cerca de 20 anos.","O BTS faz três noites no MorumBIS (28, 30 e 31/10). Em novembro, M.I.A. toca no Audio (1º/11), Hayley Williams passa pelo Rio (9/11) e por São Paulo (12 e 13/11), e CA7RIEL & Paco Amoroso fazem São Paulo (18/11) e Rio (20/11).","Em dezembro, Ed Sheeran leva a “Loop Tour” ao Nubank Parque (5 e 6/12), com FINNEAS na abertura. No mesmo fim de semana acontece o Primavera Sound São Paulo, em Interlagos."]},"en":{"slug":"international-concerts-brazil-late-2026","headline":"From ZAYN to Ed Sheeran: the international acts still coming to Brazil in 2026","summary":"October opens with ZAYN and Robbie Williams; BTS, Hayley Williams and CA7RIEL & Paco Amoroso follow, and Ed Sheeran closes the year.","body":["The last quarter of 2026 is packed with international concerts in Brazil. ZAYN kicks things off on October 10 at Nubank Parque in São Paulo, and Robbie Williams plays the same venue on October 13, his return after about 20 years.","BTS play three nights at MorumBIS (Oct 28, 30 and 31). In November, M.I.A. plays Audio (Nov 1), Hayley Williams stops in Rio (Nov 9) and São Paulo (Nov 12–13), and CA7RIEL & Paco Amoroso play São Paulo (Nov 18) and Rio (Nov 20).","In December, Ed Sheeran brings the Loop Tour to Nubank Parque (Dec 5–6), with FINNEAS opening. Primavera Sound São Paulo takes place the same weekend at Interlagos."]},"es":{"slug":"agenda-conciertos-internacionales-brasil-fin-de-2026","headline":"De ZAYN a Ed Sheeran: los shows internacionales que todavía llegan a Brasil en 2026","summary":"Octubre abre con ZAYN y Robbie Williams; luego vienen BTS, Hayley Williams y CA7RIEL & Paco Amoroso, y Ed Sheeran cierra el año.","body":["El último trimestre de 2026 llega cargado de conciertos internacionales en Brasil. ZAYN abre el 10 de octubre en el Nubank Parque de São Paulo, y Robbie Williams toca en el mismo lugar el 13 de octubre, su regreso tras unos 20 años.","BTS hará tres noches en el MorumBIS (28, 30 y 31/10). En noviembre, M.I.A. toca en Audio (1/11), Hayley Williams pasa por Río (9/11) y São Paulo (12 y 13/11), y CA7RIEL & Paco Amoroso tocan en São Paulo (18/11) y Río (20/11).","En diciembre, Ed Sheeran lleva el Loop Tour al Nubank Parque (5 y 6/12), con FINNEAS como telonero. Ese mismo fin de semana se celebra el Primavera Sound São Paulo, en Interlagos."]}}}'::jsonb),
('article', '2012', 'published', '{"id":"2012","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-26T15:00:00Z","hue":320,"personIds":["anitta"],"sources":[{"name":"POPline","url":"https://portalpopline.com.br/anitta-agenda-shows-2026/"}],"t":{"pt":{"slug":"anitta-agenda-shows-meli-music-ensaios-2027","headline":"Anitta toca no Pacaembu em outubro e já tem datas dos Ensaios de 2027","summary":"Depois do Meli Music, a cantora passa pelo Rock the Mountain e abre em janeiro a temporada de Ensaios em oito cidades.","body":["Anitta se apresenta em 17 de outubro no Meli Music, na Mercado Livre Arena Pacaembu, em São Paulo. Em novembro, ela está no line-up do Rock the Mountain, em Petrópolis (RJ).","Em janeiro de 2027 começa a nova temporada dos Ensaios da Anitta, com datas em Belém, Recife, Belo Horizonte, Brasília, Campinas, Rio de Janeiro, Curitiba e São Paulo. As apresentações em Recife e Curitiba já estão esgotadas, segundo o POPline.","A cantora mantém dois formatos de show: os Ensaios e a “EQUILIBRIVM Tour”, mais intimista e focada no álbum mais recente."]},"en":{"slug":"anitta-tour-dates-meli-music-ensaios-2027","headline":"Anitta plays Pacaembu in October and has already set her 2027 “Ensaios” dates","summary":"After Meli Music, she plays Rock the Mountain and opens her “Ensaios” season in eight cities in January.","body":["Anitta performs on October 17 at Meli Music, at the Mercado Livre Arena Pacaembu in São Paulo. In November she is on the Rock the Mountain lineup in Petrópolis, Rio de Janeiro state.","In January 2027 her new “Ensaios da Anitta” season begins, with dates in Belém, Recife, Belo Horizonte, Brasília, Campinas, Rio de Janeiro, Curitiba and São Paulo. The Recife and Curitiba shows are already sold out, per POPline.","She keeps two show formats: the “Ensaios” and the more intimate EQUILIBRIVM Tour, focused on her latest album."]},"es":{"slug":"anitta-agenda-shows-meli-music-ensaios-2027","headline":"Anitta toca en el Pacaembu en octubre y ya tiene fechas de los “Ensaios” 2027","summary":"Tras el Meli Music, pasa por Rock the Mountain y en enero abre la temporada de “Ensaios” en ocho ciudades.","body":["Anitta se presenta el 17 de octubre en el Meli Music, en el Mercado Livre Arena Pacaembu de São Paulo. En noviembre está en el cartel de Rock the Mountain, en Petrópolis (RJ).","En enero de 2027 empieza la nueva temporada de los “Ensaios da Anitta”, con fechas en Belém, Recife, Belo Horizonte, Brasilia, Campinas, Río de Janeiro, Curitiba y São Paulo. Los shows de Recife y Curitiba ya están agotados, según POPline.","La cantante mantiene dos formatos: los “Ensaios” y el EQUILIBRIVM Tour, más íntimo y centrado en su último álbum."]}}}'::jsonb),
('article', '2007', 'published', '{"id":"2007","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-09-26T12:00:00Z","hue":270,"personIds":["bts"],"sources":[{"name":"The Rio Times","url":"https://www.riotimesonline.com/bts-sao-paulo-brazil-concerts-october-28-30-31-2026-morumbis-arirang-tour/"},{"name":"Ticketmaster Brasil","url":"https://www.ticketmaster.com.br/event/bts-world-tour-arirang"}],"t":{"pt":{"slug":"bts-sao-paulo-morumbis-arirang-datas","headline":"BTS volta ao Brasil depois de sete anos com três shows no MorumBIS","summary":"A turnê “Arirang”, primeira do grupo completo após o serviço militar, passa por São Paulo em 28, 30 e 31 de outubro.","body":["O BTS se apresenta no MorumBIS, em São Paulo, nos dias 28, 30 e 31 de outubro. É a primeira passagem do grupo pelo Brasil em sete anos.","Os shows fazem parte da “BTS World Tour Arirang”, a primeira turnê com os sete integrantes depois do serviço militar. Antes do Brasil, o grupo toca em Bogotá, na Colômbia, em 2 e 3 de outubro.","Os ingressos são vendidos pela Ticketmaster Brasil, com cadastro de CPF obrigatório."]},"en":{"slug":"bts-sao-paulo-morumbis-arirang-dates","headline":"BTS return to Brazil after seven years with three shows at MorumBIS","summary":"The Arirang tour, the group’s first full-lineup trek since military service, hits São Paulo on October 28, 30 and 31.","body":["BTS will play MorumBIS stadium in São Paulo on October 28, 30 and 31, the group’s first shows in Brazil in seven years.","The dates are part of the BTS World Tour Arirang, the first tour with all seven members since their military service. Before Brazil, they play Bogotá, Colombia, on October 2 and 3.","Tickets are sold through Ticketmaster Brasil, and buyers must register a Brazilian CPF."]},"es":{"slug":"bts-sao-paulo-morumbis-arirang-fechas","headline":"BTS vuelve a Brasil tras siete años con tres shows en el MorumBIS","summary":"La gira “Arirang”, la primera del grupo completo tras el servicio militar, pasa por São Paulo el 28, 30 y 31 de octubre.","body":["BTS se presentará en el estadio MorumBIS de São Paulo el 28, 30 y 31 de octubre, sus primeros shows en Brasil en siete años.","Las fechas son parte de la BTS World Tour Arirang, la primera gira con los siete integrantes tras el servicio militar. Antes de Brasil tocan en Bogotá, Colombia, el 2 y 3 de octubre.","Las entradas se venden por Ticketmaster Brasil, con registro obligatorio de CPF."]}}}'::jsonb),
('article', '2005', 'published', '{"id":"2005","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-25T14:00:00Z","hue":20,"personIds":["taylor-swift"],"sources":[{"name":"ABC News","url":"https://abcnews.com/GMA/Culture/taylor-swift-announces-new-single-patient-zero/story?id=136657611"},{"name":"Billboard","url":"https://www.billboard.com/music/music-news/taylor-swift-life-showgirl-encore-listen-1236346593/"}],"t":{"pt":{"slug":"taylor-swift-the-life-of-a-showgirl-the-encore-patient-zero","headline":"Taylor Swift lança “The Encore” com quatro músicas inéditas e o single “Patient Zero”","summary":"As faixas extras chegam quase um ano depois de “The Life of a Showgirl”, que vendeu mais de 4 milhões de unidades na estreia.","body":["Taylor Swift lançou na sexta-feira (25) “The Life of a Showgirl: The Encore”, edição com quatro músicas novas: “Patient Zero”, “Babylon”, “Cleveland!” e “Pink Clouding”.","“Patient Zero” é o single de trabalho, e o clipe estreou no VMA. As novas faixas foram produzidas com Max Martin e Shellback, a mesma dupla do álbum original.","“The Life of a Showgirl” saiu em 3 de outubro de 2025 e bateu recorde ao passar de 4 milhões de unidades equivalentes vendidas na primeira semana."]},"en":{"slug":"taylor-swift-the-life-of-a-showgirl-the-encore-patient-zero","headline":"Taylor Swift releases “The Encore” with four new songs, led by “Patient Zero”","summary":"The bonus tracks arrive almost a year after “The Life of a Showgirl”, which moved over 4 million units in its first week.","body":["Taylor Swift released “The Life of a Showgirl: The Encore” on Friday, adding four new songs: “Patient Zero”, “Babylon”, “Cleveland!” and “Pink Clouding”.","“Patient Zero” is the single, and its video premiered at the VMAs. The new tracks were produced with Max Martin and Shellback, the team behind the original album.","“The Life of a Showgirl” came out on October 3, 2025, and set a record with more than 4 million equivalent units in its first week."]},"es":{"slug":"taylor-swift-the-life-of-a-showgirl-the-encore-patient-zero","headline":"Taylor Swift lanza “The Encore” con cuatro canciones inéditas y el sencillo “Patient Zero”","summary":"Los temas extra llegan casi un año después de “The Life of a Showgirl”, que superó los 4 millones de unidades en su debut.","body":["Taylor Swift lanzó el viernes “The Life of a Showgirl: The Encore”, con cuatro canciones nuevas: “Patient Zero”, “Babylon”, “Cleveland!” y “Pink Clouding”.","“Patient Zero” es el sencillo, y su video se estrenó en los VMA. Los temas se produjeron con Max Martin y Shellback, el mismo equipo del álbum original.","“The Life of a Showgirl” salió el 3 de octubre de 2025 y marcó un récord con más de 4 millones de unidades equivalentes en su primera semana."]}}}'::jsonb),
('article', '2004', 'published', '{"id":"2004","section":"charts","confidence":"confirmed","risk":"green","publishedAt":"2026-09-25T13:00:00Z","hue":150,"personIds":["karol-g"],"sources":[{"name":"Billboard","url":"https://www.billboard.com/music/chart-beat/karol-g-judeline-rusowsky-bby-wow-no-1-1236323969/"},{"name":"Wikipedia — Bby Wow","url":"https://en.wikipedia.org/wiki/Bby_Wow"},{"name":"Spotify Weekly Global (kworb)","url":"https://kworb.net/spotify/country/global_weekly.html"}],"t":{"pt":{"slug":"karol-g-bby-wow-numero-1-spotify-global","headline":"“BbY WOW”, de Karol G com Judeline e rusowsky, segue como a música mais ouvida do mundo no Spotify","summary":"A faixa lidera de novo o ranking semanal global e já chegou ao topo da Billboard Global 200.","body":["Karol G mantém “BbY WOW”, parceria com os espanhóis Judeline e rusowsky, em 1º lugar no ranking semanal global do Spotify, na semana encerrada em 24 de setembro.","Lançada em 7 de agosto, a música faz parte de “No Me Arrepiento de Sentir Tanto”, sexto álbum de estúdio da colombiana. Ela também alcançou o topo da Billboard Global 200 e deu a Judeline e rusowsky o primeiro 1º lugar na Hot Latin Songs.","A produção é assinada pelos três artistas, com Tainy e Omer Fedi."]},"en":{"slug":"karol-g-bby-wow-number-one-spotify-global","headline":"Karol G’s “BbY WOW” with Judeline and rusowsky stays the world’s most-streamed song on Spotify","summary":"The track tops the global weekly chart again and has already hit No. 1 on the Billboard Global 200.","body":["Karol G’s “BbY WOW”, a collaboration with Spanish artists Judeline and rusowsky, holds No. 1 on Spotify’s global weekly chart for the week ending September 24.","Released August 7, the song is from “No Me Arrepiento de Sentir Tanto”, the Colombian star’s sixth studio album. It also reached No. 1 on the Billboard Global 200 and gave Judeline and rusowsky their first Hot Latin Songs No. 1.","It was produced by the three artists with Tainy and Omer Fedi."]},"es":{"slug":"karol-g-bby-wow-numero-1-spotify-global","headline":"“BbY WOW”, de Karol G con Judeline y rusowsky, sigue siendo la canción más escuchada del mundo en Spotify","summary":"El tema lidera otra vez la lista semanal global y ya llegó al #1 del Billboard Global 200.","body":["Karol G mantiene “BbY WOW”, colaboración con los españoles Judeline y rusowsky, en el #1 de la lista semanal global de Spotify en la semana que terminó el 24 de septiembre.","Lanzada el 7 de agosto, forma parte de “No Me Arrepiento de Sentir Tanto”, sexto álbum de estudio de la colombiana. También alcanzó el #1 del Billboard Global 200 y dio a Judeline y rusowsky su primer #1 en Hot Latin Songs.","La producción es de los tres artistas junto a Tainy y Omer Fedi."]}}}'::jsonb),
('article', '2011', 'published', '{"id":"2011","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-25T10:00:00Z","hue":285,"personIds":["taylor-swift","madonna","charli-xcx"],"sources":[{"name":"DK Network — New Music Friday","url":"https://dknetwork.draftkings.com/2026/09/24/new-music-friday-release-radar-for-september-25-2026-top-albums-song-releases/"},{"name":"Paste","url":"https://www.pastemagazine.com/music/best-new-albums/best-new-albums-september-25-2026"}],"t":{"pt":{"slug":"lancamentos-da-semana-25-setembro-2026","headline":"Lançamentos da semana: Taylor Swift, Madonna com Charli xcx, Tinashe e Linkin Park ao vivo em SP","summary":"A sexta-feira (25) trouxe edição especial de Taylor, single novo de Madonna e álbum de Tinashe.","body":["O destaque da sexta-feira foi Taylor Swift, com “The Life of a Showgirl: The Encore” e o single “Patient Zero”. Madonna e Charli xcx lançaram juntas “Danceteria”, dias antes de dividirem o palco no VMA.","Tinashe apresentou o álbum “Poster”, e o Linkin Park lançou a trilha ao vivo “Unshatter”, gravada em São Paulo.","Nos singles, saíram ainda “Fireflies”, de John Legend com Pharrell Williams, “On Video”, de Phoebe Bridgers, e “Roses”, do Chvrches."]},"en":{"slug":"new-music-friday-september-25-2026","headline":"New this week: Taylor Swift, Madonna with Charli xcx, Tinashe and Linkin Park live in São Paulo","summary":"Friday brought Taylor’s special edition, a new Madonna single and Tinashe’s album.","body":["Friday’s headliner was Taylor Swift, with “The Life of a Showgirl: The Encore” and the single “Patient Zero”. Madonna and Charli xcx released “Danceteria” together, days before sharing the VMAs stage.","Tinashe dropped her album “Poster”, and Linkin Park released the live soundtrack “Unshatter”, recorded in São Paulo.","Other singles included John Legend and Pharrell Williams’ “Fireflies”, Phoebe Bridgers’ “On Video” and Chvrches’ “Roses”."]},"es":{"slug":"estrenos-de-la-semana-25-septiembre-2026","headline":"Estrenos de la semana: Taylor Swift, Madonna con Charli xcx, Tinashe y Linkin Park en vivo en São Paulo","summary":"El viernes llegó la edición especial de Taylor, un sencillo nuevo de Madonna y el álbum de Tinashe.","body":["La protagonista del viernes fue Taylor Swift, con “The Life of a Showgirl: The Encore” y el sencillo “Patient Zero”. Madonna y Charli xcx lanzaron juntas “Danceteria”, días antes de compartir escenario en los VMA.","Tinashe presentó el álbum “Poster” y Linkin Park lanzó la banda sonora en vivo “Unshatter”, grabada en São Paulo.","En sencillos también salieron “Fireflies”, de John Legend con Pharrell Williams, “On Video”, de Phoebe Bridgers, y “Roses”, de Chvrches."]}}}'::jsonb),
('article', '2009', 'published', '{"id":"2009","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-09-24T12:00:00Z","hue":165,"personIds":[],"sources":[{"name":"Showmetech","url":"https://www.showmetech.com.br/confira-lineup-do-primavera-sound-sao-paulo-2026/"}],"t":{"pt":{"slug":"primavera-sound-sao-paulo-2026-line-up","headline":"Primavera Sound São Paulo 2026 tem The Strokes, Gorillaz, FKA twigs e Lily Allen","summary":"O festival volta a Interlagos nos dias 5 e 6 de dezembro, após dois anos de pausa.","body":["O Primavera Sound São Paulo confirmou sua terceira edição para 5 e 6 de dezembro, no Autódromo de Interlagos. O festival estava parado desde 2023.","The Strokes, Gorillaz, FKA twigs e Lily Allen lideram o line-up de 37 atrações, que também tem Courtney Barnett, Yung Lean e Nation of Language.","Do Brasil, estão confirmados Ana Frango Elétrico, Gaby Amarantos, Johnny Hooker, Duquesa, Ebony e Josyara."]},"en":{"slug":"primavera-sound-sao-paulo-2026-lineup","headline":"Primavera Sound São Paulo 2026 brings The Strokes, Gorillaz, FKA twigs and Lily Allen","summary":"The festival returns to Interlagos on December 5–6 after a two-year break.","body":["Primavera Sound São Paulo confirmed its third edition for December 5–6 at the Interlagos racetrack. The festival had been on hold since 2023.","The Strokes, Gorillaz, FKA twigs and Lily Allen top a 37-act lineup that also includes Courtney Barnett, Yung Lean and Nation of Language.","Brazilian acts include Ana Frango Elétrico, Gaby Amarantos, Johnny Hooker, Duquesa, Ebony and Josyara."]},"es":{"slug":"primavera-sound-sao-paulo-2026-cartel","headline":"Primavera Sound São Paulo 2026 trae a The Strokes, Gorillaz, FKA twigs y Lily Allen","summary":"El festival vuelve a Interlagos el 5 y 6 de diciembre tras dos años de pausa.","body":["Primavera Sound São Paulo confirmó su tercera edición para el 5 y 6 de diciembre en el Autódromo de Interlagos. El festival estaba en pausa desde 2023.","The Strokes, Gorillaz, FKA twigs y Lily Allen encabezan un cartel de 37 artistas que también incluye a Courtney Barnett, Yung Lean y Nation of Language.","De Brasil están confirmados Ana Frango Elétrico, Gaby Amarantos, Johnny Hooker, Duquesa, Ebony y Josyara."]}}}'::jsonb),
('article', '2003', 'published', '{"id":"2003","section":"charts","confidence":"confirmed","risk":"green","publishedAt":"2026-09-23T15:00:00Z","hue":25,"personIds":["ella-langley"],"sources":[{"name":"Billboard","url":"https://www.billboard.com/lists/ella-langley-choosin-texas-hot-100-number-one-chart-record/"},{"name":"NBC Palm Springs / CNN Newsource","url":"https://www.nbcpalmsprings.com/entertainment-report/2026/09/23/ella-langley-sets-billboard-record-as-choosin-texas-reaches-23-weeks-at-no-1"}],"t":{"pt":{"slug":"ella-langley-choosin-texas-recorde-23-semanas-hot-100","headline":"“Choosin’ Texas”, de Ella Langley, bate o recorde de semanas em 1º na Billboard Hot 100","summary":"A música country chegou à 23ª semana no topo e superou a marca histórica da parada americana.","body":["Ella Langley fez história na Billboard Hot 100: “Choosin’ Texas” completou 23 semanas em 1º lugar, o maior número da história da parada, segundo a Billboard.","Lançada em outubro de 2025, a faixa ultrapassou o público tradicional do country. Até meados de agosto, somava mais de 911 milhões de streams nos EUA e 1,26 bilhão no mundo, de acordo com a CNN Newsource.","A música segue no topo também do Spotify americano na semana encerrada em 24 de setembro."]},"en":{"slug":"ella-langley-choosin-texas-23-weeks-hot-100-record","headline":"Ella Langley’s “Choosin’ Texas” sets the all-time record for weeks at No. 1 on the Hot 100","summary":"The country hit reached its 23rd week on top, the most in the chart’s history.","body":["Ella Langley made Billboard Hot 100 history as “Choosin’ Texas” logged its 23rd week at No. 1, the most ever, according to Billboard.","Released in October 2025, the song crossed well beyond country radio. By mid-August it had more than 911 million on-demand U.S. streams and 1.26 billion worldwide, per CNN Newsource.","It is also No. 1 on Spotify’s U.S. weekly chart for the week ending September 24."]},"es":{"slug":"ella-langley-choosin-texas-record-23-semanas-hot-100","headline":"“Choosin’ Texas”, de Ella Langley, rompe el récord de semanas en el #1 del Billboard Hot 100","summary":"El éxito country llegó a su semana 23 en la cima, la mayor cifra en la historia de la lista.","body":["Ella Langley hizo historia en el Billboard Hot 100: “Choosin’ Texas” sumó 23 semanas en el #1, la mayor cantidad de la historia, según Billboard.","Lanzada en octubre de 2025, la canción superó el público tradicional del country. A mediados de agosto acumulaba más de 911 millones de streams en EE. UU. y 1.260 millones en el mundo, según CNN Newsource.","También es #1 en la lista semanal de Spotify en EE. UU. en la semana que terminó el 24 de septiembre."]}}}'::jsonb),
('article', '2006', 'published', '{"id":"2006","section":"creators","confidence":"confirmed","risk":"green","publishedAt":"2026-09-21T16:00:00Z","hue":190,"personIds":["travis-scott","morgan-wallen","rauw-alejandro","ca7riel-paco-amoroso"],"sources":[{"name":"Consequence","url":"https://consequence.net/2026/09/grand-theft-auto-vi-announces-soundtrack-album/"},{"name":"Vibe","url":"https://www.vibe.com/music/music-news/grand-theft-auto-vi-album-travis-scott-morgan-wallen-1235188682/"}],"t":{"pt":{"slug":"gta-vi-the-album-trilha-travis-scott-morgan-wallen","headline":"GTA VI terá álbum com 34 músicas inéditas de Travis Scott, Morgan Wallen, Rauw Alejandro e mais","summary":"“Grand Theft Auto VI: The Album” sai em 19 de novembro, junto com o jogo.","body":["A Rockstar Games anunciou “Grand Theft Auto VI: The Album”, com 34 músicas originais. Seis já foram lançadas e as outras 28 chegam em 19 de novembro, mesmo dia do lançamento do jogo.","Entre os primeiros nomes estão Travis Scott, Morgan Wallen, Keith Richards, Future, Metro Boomin, PinkPantheress, Fred again.., Rauw Alejandro e a dupla argentina CA7RIEL & Paco Amoroso. A faixa de Travis Scott, “RHYNO”, tem produção de Guy-Manuel de Homem-Christo, ex-Daft Punk.","A pré-venda em vinil e CD abriu em 17 de setembro. “Last Thing You Need”, de Morgan Wallen, estreou no top 10 do Spotify americano."]},"en":{"slug":"gta-vi-the-album-soundtrack-travis-scott-morgan-wallen","headline":"GTA VI gets a 34-song original album featuring Travis Scott, Morgan Wallen, Rauw Alejandro and more","summary":"“Grand Theft Auto VI: The Album” arrives November 19, alongside the game.","body":["Rockstar Games announced “Grand Theft Auto VI: The Album”, with 34 original songs. Six are already out and the remaining 28 arrive on November 19, the game’s release date.","Early names include Travis Scott, Morgan Wallen, Keith Richards, Future, Metro Boomin, PinkPantheress, Fred again.., Rauw Alejandro and Argentine duo CA7RIEL & Paco Amoroso. Travis Scott’s “RHYNO” is produced by former Daft Punk member Guy-Manuel de Homem-Christo.","Vinyl and CD pre-orders opened September 17. Morgan Wallen’s “Last Thing You Need” debuted in the top 10 of Spotify’s U.S. chart."]},"es":{"slug":"gta-vi-the-album-banda-sonora-travis-scott-morgan-wallen","headline":"GTA VI tendrá un álbum de 34 canciones inéditas con Travis Scott, Morgan Wallen, Rauw Alejandro y más","summary":"“Grand Theft Auto VI: The Album” sale el 19 de noviembre, junto con el juego.","body":["Rockstar Games anunció “Grand Theft Auto VI: The Album”, con 34 canciones originales. Seis ya salieron y las otras 28 llegan el 19 de noviembre, el día del lanzamiento del juego.","Entre los primeros nombres están Travis Scott, Morgan Wallen, Keith Richards, Future, Metro Boomin, PinkPantheress, Fred again.., Rauw Alejandro y el dúo argentino CA7RIEL & Paco Amoroso. “RHYNO”, de Travis Scott, tiene producción de Guy-Manuel de Homem-Christo, ex Daft Punk.","La preventa en vinilo y CD abrió el 17 de septiembre. “Last Thing You Need”, de Morgan Wallen, debutó en el top 10 de Spotify en EE. UU."]}}}'::jsonb),
('article', '2016', 'published', '{"id":"2016","section":"events","confidence":"reported","risk":"green","publishedAt":"2026-09-14T18:00:00Z","hue":10,"personIds":["elton-john","demi-lovato","ivete-sangalo","stray-kids","luisa-sonza","alok"],"sources":[{"name":"Terra","url":"https://www.terra.com.br/diversao/musica/rock-in-rio/balanco-rock-in-rio-2026-os-melhores-e-os-piores-shows-do-festival,4a4d1ffbba949179bfcf2650bd416966v690jlth.html"}],"t":{"pt":{"slug":"rock-in-rio-2026-melhores-e-piores-shows-critica","headline":"Rock in Rio 2026: os shows que a crítica amou — e os que dividiram opiniões","summary":"Elton John, Jamiroquai e Demi Lovato estão entre os mais elogiados; Maroon 5 e Machine Gun Kelly receberam as piores avaliações.","body":["No balanço do Terra, o topo ficou com Elton John, pela voz firme em mais de duas horas de clássicos, seguido de Jamiroquai e do encontro de Roupa Nova com Guilherme Arantes. Demi Lovato puxou uma das maiores plateias do festival, e Ivete Sangalo mostrou regularidade em sua 20ª participação no evento.","Entre os shows com avaliação negativa estão Machine Gun Kelly, considerado deslocado no dia do metal, e Maroon 5, pelo repertório previsível. O crítico também não se convenceu com o show de Luísa Sonza, que misturou bossa nova e funk, e achou o set de Calvin Harris menos marcante que o de Alok."]},"en":{"slug":"rock-in-rio-2026-best-and-worst-shows-critics","headline":"Rock in Rio 2026: the shows critics loved — and the ones that split opinions","summary":"Elton John, Jamiroquai and Demi Lovato were among the most praised; Maroon 5 and Machine Gun Kelly got the worst reviews.","body":["In Terra’s wrap-up, Elton John topped the list for holding his voice through over two hours of classics, followed by Jamiroquai and the pairing of Roupa Nova with Guilherme Arantes. Demi Lovato drew one of the festival’s biggest crowds, and Ivete Sangalo was consistent in her 20th appearance at the event.","On the negative side were Machine Gun Kelly, seen as out of place on metal day, and Maroon 5, for a predictable setlist. The critic was also unconvinced by Luísa Sonza’s mix of bossa nova and funk, and found Calvin Harris less memorable than Alok."]},"es":{"slug":"rock-in-rio-2026-mejores-y-peores-shows-critica","headline":"Rock in Rio 2026: los shows que la crítica amó y los que dividieron opiniones","summary":"Elton John, Jamiroquai y Demi Lovato, entre los más elogiados; Maroon 5 y Machine Gun Kelly recibieron las peores reseñas.","body":["En el balance de Terra, el primer lugar fue para Elton John, por sostener la voz en más de dos horas de clásicos, seguido de Jamiroquai y del encuentro de Roupa Nova con Guilherme Arantes. Demi Lovato reunió uno de los públicos más grandes, e Ivete Sangalo se mostró sólida en su 20.ª participación en el festival.","Entre las peores evaluaciones quedaron Machine Gun Kelly, fuera de lugar en el día del metal, y Maroon 5, por un repertorio previsible. El crítico tampoco quedó convencido con el show de Luísa Sonza, que mezcló bossa nova y funk, y consideró el set de Calvin Harris menos memorable que el de Alok."]}}}'::jsonb),
('article', '2013', 'published', '{"id":"2013","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-09-14T13:00:00Z","hue":30,"personIds":["elton-john","stray-kids","ivete-sangalo","gilberto-gil"],"sources":[{"name":"GMC Online","url":"https://gmconline.com.br/entretenimento/rock-in-rio-2026-reune-700-mil-pessoas-em-sete-dias-edicao-2028-esta-confirmada/"},{"name":"The Rio Times","url":"https://www.riotimesonline.com/rock-in-rio-2026-brazil-september-4-13-elton-john-stray-kids-lineup/"}],"t":{"pt":{"slug":"rock-in-rio-2026-balanco-700-mil-pessoas-2028-confirmado","headline":"Rock in Rio 2026 termina com 700 mil pessoas e edição de 2028 já confirmada","summary":"Os sete dias de festival tiveram chuva quase todo dia, despedida de Elton John e o primeiro headliner de K-pop do Palco Mundo.","body":["O Rock in Rio 2026 reuniu 700 mil pessoas em sete dias na Cidade do Rock, segundo a organização. Metade do público veio de fora do estado do Rio, e o festival contou visitantes de 89 países.","A chuva caiu em todos os dias, menos na abertura, e virou parte da história desta edição. No palco, os destaques foram a despedida de Elton John do Brasil, o encontro dele com Gilberto Gil nos bastidores e o Stray Kids, primeiro grupo de K-pop a fechar uma noite no Palco Mundo.","A organização estimou impacto de R$ 3,36 bilhões na economia e já confirmou a próxima edição para setembro de 2028. O The Town, festival irmão em São Paulo, volta em setembro de 2027."]},"en":{"slug":"rock-in-rio-2026-recap-700000-fans-2028-confirmed","headline":"Rock in Rio 2026 wraps with 700,000 fans and a 2028 edition already confirmed","summary":"Seven days marked by near-daily rain, Elton John’s farewell to Brazil and the Palco Mundo’s first K-pop headliner.","body":["Rock in Rio 2026 drew 700,000 people over seven days at the Cidade do Rock, according to organizers. Half the crowd came from outside Rio de Janeiro state, with visitors from 89 countries.","Rain fell every day except opening night and became part of this edition’s story. On stage, the highlights were Elton John’s farewell to Brazil, his backstage meeting with Gilberto Gil and Stray Kids, the first K-pop group to headline the Palco Mundo.","Organizers estimated an economic impact of R$3.36 billion and confirmed the next edition for September 2028. Sister festival The Town returns to São Paulo in September 2027."]},"es":{"slug":"rock-in-rio-2026-balance-700-mil-personas-2028-confirmado","headline":"Rock in Rio 2026 cierra con 700 mil personas y la edición 2028 ya confirmada","summary":"Siete días con lluvia casi diaria, la despedida de Elton John de Brasil y el primer headliner de K-pop del Palco Mundo.","body":["Rock in Rio 2026 reunió a 700 mil personas en siete días en la Cidade do Rock, según la organización. La mitad del público llegó de fuera del estado de Río, con visitantes de 89 países.","Llovió todos los días menos en la apertura, y eso marcó esta edición. En el escenario destacaron la despedida de Elton John de Brasil, su encuentro con Gilberto Gil tras bastidores y Stray Kids, el primer grupo de K-pop en cerrar una noche en el Palco Mundo.","La organización estimó un impacto de R$ 3.360 millones en la economía y ya confirmó la próxima edición para septiembre de 2028. The Town, su festival hermano en São Paulo, vuelve en septiembre de 2027."]}},"factBox":{"pt":{"known":["Público total: 700 mil pessoas em 7 dias","Visitantes de 89 países","Próxima edição: setembro de 2028","The Town volta em setembro de 2027"],"unknown":[]},"en":{"known":["Total attendance: 700,000 over 7 days","Visitors from 89 countries","Next edition: September 2028","The Town returns in September 2027"],"unknown":[]},"es":{"known":["Público total: 700 mil personas en 7 días","Visitantes de 89 países","Próxima edición: septiembre de 2028","The Town vuelve en septiembre de 2027"],"unknown":[]}}}'::jsonb),
('article', '2015', 'published', '{"id":"2015","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-12T11:00:00Z","hue":260,"personIds":["stray-kids"],"sources":[{"name":"GMC Online","url":"https://gmconline.com.br/entretenimento/rock-in-rio-2026-reune-700-mil-pessoas-em-sete-dias-edicao-2028-esta-confirmada/"},{"name":"setlist.fm","url":"https://www.setlist.fm/setlist/stray-kids/2026/parque-olimpico-palco-mundo-rio-de-janeiro-brazil-1b4c8128.html"},{"name":"Terra","url":"https://www.terra.com.br/diversao/musica/rock-in-rio/balanco-rock-in-rio-2026-os-melhores-e-os-piores-shows-do-festival,4a4d1ffbba949179bfcf2650bd416966v690jlth.html"}],"t":{"pt":{"slug":"stray-kids-primeiro-kpop-headliner-palco-mundo-rock-in-rio","headline":"Stray Kids faz história como o primeiro grupo de K-pop a fechar o Palco Mundo do Rock in Rio","summary":"O show de 11 de setembro teve coreografias sem erro, telões gigantes e alerta da produção para a lotação na grade.","body":["O Stray Kids virou o primeiro grupo de K-pop a ser atração principal do Palco Mundo, na abertura do segundo fim de semana do Rock in Rio, em 11 de setembro.","A crítica elogiou a precisão das coreografias e o uso dos telões. Durante o show, a produção pediu que os fãs se afastassem da grade por causa da lotação na frente do palco."]},"en":{"slug":"stray-kids-first-kpop-headliner-palco-mundo-rock-in-rio","headline":"Stray Kids make history as the first K-pop group to headline Rock in Rio’s Palco Mundo","summary":"The September 11 show brought flawless choreography, giant screens and crowd-safety warnings from the production.","body":["Stray Kids became the first K-pop group to headline the Palco Mundo, opening Rock in Rio’s second weekend on September 11.","Critics praised the precise choreography and the use of the giant screens. During the set, the production asked fans to step back from the barrier due to crowd density at the front."]},"es":{"slug":"stray-kids-primer-kpop-headliner-palco-mundo-rock-in-rio","headline":"Stray Kids hace historia como el primer grupo de K-pop en encabezar el Palco Mundo de Rock in Rio","summary":"El show del 11 de septiembre tuvo coreografías impecables, pantallas gigantes y avisos de seguridad de la producción.","body":["Stray Kids se convirtió en el primer grupo de K-pop en encabezar el Palco Mundo, en la apertura del segundo fin de semana de Rock in Rio, el 11 de septiembre.","La crítica elogió la precisión de las coreografías y el uso de las pantallas. Durante el show, la producción pidió a los fans alejarse de la valla por la densidad del público."]}}}'::jsonb),
('article', '2014', 'published', '{"id":"2014","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-09-08T12:00:00Z","hue":45,"personIds":["elton-john","gilberto-gil"],"sources":[{"name":"Rolling Stone Brasil","url":"https://rollingstone.com.br/musica/elton-john-enaltece-show-no-rock-in-rio-2026-pais-lindo-e-povo-maravilhoso/"},{"name":"Billboard","url":"https://www.billboard.com/music/music-news/elton-john-2026-rock-in-rio-recap-1236336050/"}],"t":{"pt":{"slug":"elton-john-despedida-brasil-rock-in-rio-2026","headline":"Elton John se despede do Brasil no Rock in Rio: “país lindo e povo maravilhoso”","summary":"Aos 79 anos, o cantor fez seu primeiro show no país em nove anos e disse que não pretende voltar a fazer turnês.","body":["Elton John fechou o Palco Mundo na segunda-feira, 7 de setembro, com um show de 24 músicas que a crítica chamou de histórico. Foi a primeira apresentação dele no Brasil em nove anos.","No dia seguinte, o cantor agradeceu ao público nas redes e disse que a noite tinha sido incrível. Ele lamentou não ter incluído a América do Sul na turnê de despedida encerrada em 2023 e tratou o show como uma forma de acertar essa dívida com os fãs brasileiros.","Elton confirmou que não planeja novas turnês nem shows solo, por causa de questões de saúde. Nos bastidores, ele se encontrou com Gilberto Gil, que também se apresentou no festival."]},"en":{"slug":"elton-john-farewell-brazil-rock-in-rio-2026","headline":"Elton John says goodbye to Brazil at Rock in Rio: “a beautiful country, wonderful people”","summary":"At 79, he played his first show in the country in nine years and said he has no plans to tour again.","body":["Elton John closed the Palco Mundo on Monday, September 7, with a 24-song set critics called historic. It was his first show in Brazil in nine years.","The next day he thanked fans online, calling the night incredible. He said he regretted leaving South America out of the farewell tour that ended in 2023 and framed the show as settling that debt with Brazilian fans.","He confirmed he has no plans for new tours or solo shows due to health issues. Backstage, he met Gilberto Gil, who also played the festival."]},"es":{"slug":"elton-john-despedida-brasil-rock-in-rio-2026","headline":"Elton John se despide de Brasil en Rock in Rio: “un país hermoso y un pueblo maravilloso”","summary":"A los 79 años hizo su primer show en el país en nueve años y dijo que no planea volver a salir de gira.","body":["Elton John cerró el Palco Mundo el lunes 7 de septiembre con un show de 24 canciones que la crítica calificó de histórico. Fue su primera presentación en Brasil en nueve años.","Al día siguiente agradeció al público en redes y dijo que la noche había sido increíble. Lamentó no haber incluido Sudamérica en la gira de despedida que terminó en 2023 y presentó el show como una forma de saldar esa deuda con los fans brasileños.","Confirmó que no planea nuevas giras ni shows solistas por problemas de salud. Tras bastidores se encontró con Gilberto Gil, que también tocó en el festival."]}}}'::jsonb),
('article', '2030', 'published', '{"id":"2030","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-07-24T12:00:00Z","hue":40,"personIds":["anitta"],"sources":[{"name":"Billboard Brasil","url":"https://billboard.com.br/anitta-novo-album-tudo-sobre/"}],"t":{"pt":{"slug":"anitta-equilibrivm-ii-maria-bethania-alceu-valenca","headline":"Anitta lança “EQUILIBRIVM II”, com Maria Bethânia, Alceu Valença e tambores de candomblé","summary":"O nono álbum da cantora fala de amor, espiritualidade e ancestralidade e chega com um filme musical.","body":["Anitta lançou em 23 de julho “EQUILIBRIVM II”, continuação do projeto iniciado em abril e nono álbum da carreira. São 19 faixas que misturam tambores de candomblé com funk, reggae e forró.","O disco tem participações de Maria Bethânia, Alceu Valença, Mart’nália, MC Tha e Mestrinho, entre outros, e uma versão em espanhol de “Azul”, de Djavan. A cantora disse que se colocou inteira no trabalho, cheio de espiritualidade e da sua visão de mundo.","O lançamento veio acompanhado de um curta musical disponível no Globoplay e no YouTube."]},"en":{"slug":"anitta-equilibrivm-ii-maria-bethania-alceu-valenca","headline":"Anitta releases “EQUILIBRIVM II” with Maria Bethânia, Alceu Valença and candomblé drums","summary":"Her ninth album explores love, spirituality and ancestry and arrives with a musical short film.","body":["Anitta released “EQUILIBRIVM II” on July 23, the continuation of the project she began in April and her ninth album. Its 19 tracks blend candomblé drums with funk, reggae and forró.","Guests include Maria Bethânia, Alceu Valença, Mart’nália, MC Tha and Mestrinho, among others, plus a Spanish-language cover of Djavan’s “Azul”. She said she put all of herself into the record, which carries her spirituality and worldview.","It comes with a musical short film on Globoplay and YouTube."]},"es":{"slug":"anitta-equilibrivm-ii-maria-bethania-alceu-valenca","headline":"Anitta lanza “EQUILIBRIVM II”, con Maria Bethânia, Alceu Valença y tambores de candomblé","summary":"Su noveno álbum habla de amor, espiritualidad y ancestralidad, y llega con un cortometraje musical.","body":["Anitta lanzó el 23 de julio “EQUILIBRIVM II”, continuación del proyecto iniciado en abril y noveno álbum de su carrera. Son 19 canciones que mezclan tambores de candomblé con funk, reggae y forró.","Cuenta con Maria Bethânia, Alceu Valença, Mart’nália, MC Tha y Mestrinho, entre otros, además de una versión en español de “Azul”, de Djavan. La cantante dijo que se entregó por completo en este trabajo, lleno de espiritualidad y de su visión del mundo.","El lanzamiento llegó con un cortometraje musical disponible en Globoplay y YouTube."]}}}'::jsonb),
('article', '2028', 'published', '{"id":"2028","section":"gossip","confidence":"confirmed","risk":"green","publishedAt":"2026-07-04T18:00:00Z","hue":320,"personIds":["taylor-swift","travis-kelce"],"sources":[{"name":"Good Morning America","url":"https://www.goodmorningamerica.com/culture/story/taylor-swift-travis-kelces-2nd-wedding-event-expected-134426168"},{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wedding_of_Taylor_Swift_and_Travis_Kelce"}],"t":{"pt":{"slug":"taylor-swift-travis-kelce-casamento-nova-york-adam-sandler","headline":"Taylor Swift e Travis Kelce se casam em Nova York com Adam Sandler celebrando a cerimônia","summary":"O casamento foi confirmado pela equipe da cantora; a festa teve cerca de mil convidados e regra de celular proibido.","body":["Taylor Swift e Travis Kelce se casaram em Nova York, numa celebração de dois dias em 3 e 4 de julho. Uma representante da cantora confirmou o casamento à ABC News.","O ator Adam Sandler celebrou a cerimônia. O irmão de Taylor, Austin, e o de Travis, Jason, foram os únicos padrinhos. Os noivos usaram Dior, e o vestido dela foi assinado por Jonathan Anderson.","Entre os cerca de mil convidados estavam Hugh Grant, Ethan Hawke, Jason Sudeikis e Benson Boone. Celulares foram proibidos para convidados e equipe. O noivado havia sido anunciado em agosto de 2025."]},"en":{"slug":"taylor-swift-travis-kelce-wedding-new-york-adam-sandler","headline":"Taylor Swift and Travis Kelce marry in New York, with Adam Sandler officiating","summary":"Her team confirmed the wedding; the two-day celebration had around 1,000 guests and a strict no-phone rule.","body":["Taylor Swift and Travis Kelce married in New York during a two-day celebration on July 3 and 4. A representative for Swift confirmed the wedding to ABC News.","Adam Sandler officiated. Swift’s brother Austin and Kelce’s brother Jason were the only members of the wedding party. Both wore Dior, with her gown designed by Jonathan Anderson.","The roughly 1,000 guests included Hugh Grant, Ethan Hawke, Jason Sudeikis and Benson Boone, and phones were banned for guests and staff. The couple announced their engagement in August 2025."]},"es":{"slug":"taylor-swift-travis-kelce-boda-nueva-york-adam-sandler","headline":"Taylor Swift y Travis Kelce se casan en Nueva York con Adam Sandler como oficiante","summary":"Su equipo confirmó la boda; la celebración de dos días tuvo cerca de mil invitados y celulares prohibidos.","body":["Taylor Swift y Travis Kelce se casaron en Nueva York en una celebración de dos días, el 3 y 4 de julio. Una representante de la cantante lo confirmó a ABC News.","Adam Sandler ofició la ceremonia. Austin, hermano de Taylor, y Jason, hermano de Travis, fueron los únicos padrinos. Ambos vistieron Dior, y el vestido de ella fue diseñado por Jonathan Anderson.","Entre los cerca de mil invitados estuvieron Hugh Grant, Ethan Hawke, Jason Sudeikis y Benson Boone, y se prohibieron los celulares. El compromiso se había anunciado en agosto de 2025."]}}}'::jsonb),
('article', '2018', 'published', '{"id":"2018","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-06-13T12:00:00Z","hue":345,"personIds":["luisa-sonza","pabllo-vittar"],"sources":[{"name":"CNN Brasil","url":"https://www.cnnbrasil.com.br/pop/musica/luisa-sonza-estreia-turne-com-pedido-de-noivado-e-performance-de-novos-hits/"}],"t":{"pt":{"slug":"luisa-sonza-estreia-turne-brutal-paraiso-rio-pedido-de-noivado","headline":"Luísa Sonza estreia a turnê “Brutal Paraíso” no Rio com pedido de noivado na plateia","summary":"No show de Dia dos Namorados, um fã pediu o namorado em casamento e a cantora abençoou o casal no palco.","body":["Luísa Sonza estreou a turnê “Brutal Paraíso” em 12 de junho, no Jockey Club do Rio, dentro de uma programação de Dia dos Namorados que também teve Pabllo Vittar.","O momento mais comentado foi um pedido de noivado entre dois fãs. A cantora parou o show, celebrou com o casal e pediu que eles cuidassem um do outro.","O repertório teve “Depois do Fim” ao vivo pela primeira vez, além de “Chico” e das faixas do novo álbum, com figurinos e coreografias no visual do disco."]},"en":{"slug":"luisa-sonza-brutal-paraiso-tour-premiere-rio-proposal","headline":"Luísa Sonza opens the “Brutal Paraíso” tour in Rio with a marriage proposal in the crowd","summary":"At the Valentine’s Day show in Brazil, a fan proposed to his boyfriend and the singer blessed the couple from the stage.","body":["Luísa Sonza kicked off the “Brutal Paraíso” tour on June 12 at Rio’s Jockey Club, part of a Brazilian Valentine’s Day event that also featured Pabllo Vittar.","The most talked-about moment was a proposal between two fans. She paused the show, celebrated with the couple and told them to take care of each other.","The setlist included the live debut of “Depois do Fim”, plus “Chico” and songs from the new album, with costumes and choreography matching its visual concept."]},"es":{"slug":"luisa-sonza-estrena-gira-brutal-paraiso-rio-propuesta","headline":"Luísa Sonza estrena la gira “Brutal Paraíso” en Río con una propuesta de matrimonio en el público","summary":"En el show del Día de los Enamorados brasileño, un fan le pidió matrimonio a su novio y la cantante bendijo a la pareja.","body":["Luísa Sonza estrenó la gira “Brutal Paraíso” el 12 de junio en el Jockey Club de Río, dentro de un evento del Día de los Enamorados que también tuvo a Pabllo Vittar.","El momento más comentado fue una propuesta de matrimonio entre dos fans. La cantante detuvo el show, celebró con la pareja y les pidió que se cuidaran mutuamente.","El repertorio incluyó el estreno en vivo de “Depois do Fim”, además de “Chico” y temas del nuevo álbum, con vestuario y coreografías acordes al disco."]}}}'::jsonb),
('article', '2027', 'published', '{"id":"2027","section":"movies-tv","confidence":"confirmed","risk":"green","publishedAt":"2026-04-22T03:00:00Z","hue":60,"personIds":["ana-paula-renault"],"sources":[{"name":"CNN Brasil","url":"https://www.cnnbrasil.com.br/pop/bbb/ana-paula-milena-e-juliano-quanto-cada-finalista-ganhou-no-bbb-26/"}],"t":{"pt":{"slug":"bbb-26-ana-paula-renault-campea-75-por-cento","headline":"Ana Paula Renault vence o BBB 26 com 75,94% dos votos e leva o maior prêmio da história","summary":"A campeã ganhou R$ 5,7 milhões; Milena Moreira e Juliano Floss completaram o pódio.","body":["Ana Paula Renault é a campeã do BBB 26. Na final de 21 de abril, ela recebeu 75,94% dos votos e levou R$ 5,7 milhões, o maior prêmio já pago pelo reality.","Milena Moreira ficou em segundo lugar e Juliano Floss em terceiro. Os três finalistas ganharam apartamentos, e a vencedora ainda levou um carro e R$ 50 mil de uma dinâmica do programa."]},"en":{"slug":"bbb-26-ana-paula-renault-wins-75-percent","headline":"Ana Paula Renault wins Big Brother Brasil 26 with 75.94% of the vote and a record prize","summary":"She took home R$5.7 million; Milena Moreira and Juliano Floss rounded out the top three.","body":["Ana Paula Renault won Big Brother Brasil 26. In the April 21 finale she received 75.94% of the vote and R$5.7 million, the largest prize in the show’s history.","Milena Moreira finished second and Juliano Floss third. All three finalists won apartments, and the winner also took a car and R$50,000 from an in-game challenge."]},"es":{"slug":"bbb-26-ana-paula-renault-campeona-75-por-ciento","headline":"Ana Paula Renault gana el BBB 26 con el 75,94% de los votos y el mayor premio de la historia","summary":"La ganadora se llevó R$ 5,7 millones; Milena Moreira y Juliano Floss completaron el podio.","body":["Ana Paula Renault es la campeona de Big Brother Brasil 26. En la final del 21 de abril obtuvo el 75,94% de los votos y R$ 5,7 millones, el mayor premio del reality.","Milena Moreira quedó segunda y Juliano Floss tercero. Los tres finalistas ganaron apartamentos, y la campeona además se llevó un auto y R$ 50 mil de una dinámica del programa."]}}}'::jsonb),
('article', '2020', 'published', '{"id":"2020","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-04-13T12:00:00Z","hue":150,"personIds":["karol-g","j-balvin","peso-pluma","becky-g"],"sources":[{"name":"Foothill Dragon Press","url":"https://foothilldragonpress.org/291354/a-latest/coachella-2026-a-overview-of-the-headlining-performances/"},{"name":"CBS News","url":"https://www.cbsnews.com/amp/losangeles/news/coachella-2026-lineup-sabrina-carpenter-justin-bieber-anyma-and-karol-g-headliners"}],"t":{"pt":{"slug":"karol-g-coachella-2026-primeira-latina-headliner","headline":"Karol G é a primeira mulher latina a fechar o Coachella e leva J Balvin e Peso Pluma ao palco","summary":"O show de domingo teve seis trocas de figurino, sete convidados e fogos no encerramento.","body":["Karol G encerrou o primeiro fim de semana do Coachella 2026, em 12 de abril, como a primeira mulher latina a ser atração principal do festival.","O show teve seis trocas de figurino e uma lista longa de convidados: Becky G, Mariah Angeliq, Greg Gonzalez, Wisin, J Balvin, Ryan Castro e Peso Pluma.","No fim, com fogos, a colombiana anunciou uma nova turnê e falou sobre a representatividade da comunidade latina."]},"en":{"slug":"karol-g-coachella-2026-first-latina-headliner","headline":"Karol G becomes the first Latina to headline Coachella, bringing out J Balvin and Peso Pluma","summary":"Her Sunday set featured six costume changes, seven guests and a fireworks finale.","body":["Karol G closed Coachella 2026’s first weekend on April 12 as the first Latina to headline the festival.","The set had six costume changes and a long list of guests: Becky G, Mariah Angeliq, Greg Gonzalez, Wisin, J Balvin, Ryan Castro and Peso Pluma.","She ended with fireworks, announced a new tour and spoke about representation for the Latino community."]},"es":{"slug":"karol-g-coachella-2026-primera-latina-headliner","headline":"Karol G es la primera mujer latina en encabezar Coachella y sube a J Balvin y Peso Pluma al escenario","summary":"Su show del domingo tuvo seis cambios de vestuario, siete invitados y fuegos artificiales al final.","body":["Karol G cerró el primer fin de semana de Coachella 2026, el 12 de abril, como la primera mujer latina en encabezar el festival.","El show tuvo seis cambios de vestuario y una larga lista de invitados: Becky G, Mariah Angeliq, Greg Gonzalez, Wisin, J Balvin, Ryan Castro y Peso Pluma.","Al final, con fuegos artificiales, anunció una nueva gira y habló de la representación de la comunidad latina."]}}}'::jsonb),
('article', '2021', 'published', '{"id":"2021","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-04-12T08:00:00Z","hue":215,"personIds":["justin-bieber","billie-eilish","sza"],"sources":[{"name":"Foothill Dragon Press","url":"https://foothilldragonpress.org/291354/a-latest/coachella-2026-a-overview-of-the-headlining-performances/"}],"t":{"pt":{"slug":"justin-bieber-bieberchella-coachella-2026-billie-eilish-sza","headline":"“Bieberchella”: Justin Bieber domina o sábado do Coachella com Billie Eilish e SZA","summary":"O headliner misturou músicas novas, vídeos antigos do YouTube e memes, e recebeu também Sexyy Red e Big Sean.","body":["Justin Bieber fechou o sábado do Coachella 2026 num show que os fãs apelidaram de “Bieberchella”. O repertório juntou as faixas mais recentes a vídeos nostálgicos do início da carreira no YouTube e compilações de memes.","O cantor recebeu Billie Eilish, SZA, Sexyy Red e Big Sean, alternando momentos mais delicados com trechos de rap e R&B."]},"en":{"slug":"justin-bieber-bieberchella-coachella-2026-billie-eilish-sza","headline":"“Bieberchella”: Justin Bieber owns Coachella Saturday with Billie Eilish and SZA","summary":"The headliner mixed new songs with vintage YouTube clips and memes, and also brought out Sexyy Red and Big Sean.","body":["Justin Bieber closed Coachella 2026’s Saturday with a set fans nicknamed “Bieberchella”. It blended his newest songs with nostalgic clips from his early YouTube days and meme montages.","He brought out Billie Eilish, SZA, Sexyy Red and Big Sean, shifting between tender moments and rap and R&B stretches."]},"es":{"slug":"justin-bieber-bieberchella-coachella-2026-billie-eilish-sza","headline":"“Bieberchella”: Justin Bieber domina el sábado de Coachella con Billie Eilish y SZA","summary":"El headliner mezcló canciones nuevas, videos antiguos de YouTube y memes, y también invitó a Sexyy Red y Big Sean.","body":["Justin Bieber cerró el sábado de Coachella 2026 con un show que los fans apodaron “Bieberchella”. Juntó sus temas más recientes con videos nostálgicos de sus inicios en YouTube y recopilaciones de memes.","Invitó a Billie Eilish, SZA, Sexyy Red y Big Sean, alternando momentos íntimos con tramos de rap y R&B."]}}}'::jsonb),
('article', '2022', 'published', '{"id":"2022","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-04-11T08:00:00Z","hue":20,"personIds":["sabrina-carpenter","madonna"],"sources":[{"name":"Foothill Dragon Press","url":"https://foothilldragonpress.org/291354/a-latest/coachella-2026-a-overview-of-the-headlining-performances/"}],"t":{"pt":{"slug":"sabrina-carpenter-coachella-2026-madonna","headline":"Sabrina Carpenter abre o Coachella como headliner e chama Madonna para um dueto","summary":"O show de sexta teve trocas de figurino e clássicos de Madonna cantados pelas duas.","body":["Sabrina Carpenter foi a atração principal da sexta-feira do Coachella 2026, com um show cheio de trocas de figurino e hits como “Espresso”.","O ponto alto foi a entrada de Madonna, que cantou clássicos ao lado dela. As duas voltariam a se encontrar meses depois: dividiram o palco na abertura do VMA e venceram Melhor Colaboração com “Bring Your Love”."]},"en":{"slug":"sabrina-carpenter-coachella-2026-madonna","headline":"Sabrina Carpenter opens Coachella as headliner and brings out Madonna for a duet","summary":"Her Friday set featured costume changes and Madonna classics sung together.","body":["Sabrina Carpenter headlined Coachella 2026’s Friday with a set full of costume changes and hits like “Espresso”.","The peak was Madonna’s surprise appearance to sing classics with her. The two reunited months later, opening the VMAs together and winning Best Collaboration for “Bring Your Love”."]},"es":{"slug":"sabrina-carpenter-coachella-2026-madonna","headline":"Sabrina Carpenter abre Coachella como headliner e invita a Madonna a un dueto","summary":"Su show del viernes tuvo cambios de vestuario y clásicos de Madonna cantados a dúo.","body":["Sabrina Carpenter encabezó el viernes de Coachella 2026 con un show lleno de cambios de vestuario y éxitos como “Espresso”.","El momento cumbre fue la aparición de Madonna para cantar clásicos con ella. Meses después volvieron a coincidir: abrieron juntas los VMA y ganaron Mejor Colaboración con “Bring Your Love”."]}}}'::jsonb),
('article', '2017', 'published', '{"id":"2017","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-04-07T15:00:00Z","hue":330,"personIds":["luisa-sonza"],"sources":[{"name":"Wikipedia — Brutal Paraíso","url":"https://en.wikipedia.org/wiki/Brutal_Para%C3%ADso"}],"t":{"pt":{"slug":"luisa-sonza-lanca-brutal-paraiso-quinto-album","headline":"Luísa Sonza lança “Brutal Paraíso”, álbum de 23 faixas com Young Miko e Sebastián Yatra","summary":"O quinto disco mistura pop, bossa nova, funk, rock e eletrônico e teve 4,1 milhões de streams nas primeiras 24 horas.","body":["Luísa Sonza lançou em 7 de abril “Brutal Paraíso”, seu quinto álbum de estúdio. São 23 faixas e mais de uma hora de música, organizadas em três blocos que vão da introspecção à sensualidade e ao drama.","O disco foi antecedido pelos singles “Telefone” e “Fruto do Tempo” e tem participações de Xamã, Young Miko, Sebastián Yatra, MC Morena, MC Meno K e MC Paiva.","Nas primeiras 24 horas, somou 4,1 milhões de streams no Spotify e colocou 13 faixas no Top 200 diário do Brasil. A crítica elogiou a ambição, mas parte dela apontou excesso de duração."]},"en":{"slug":"luisa-sonza-releases-brutal-paraiso-fifth-album","headline":"Luísa Sonza releases “Brutal Paraíso”, a 23-track album with Young Miko and Sebastián Yatra","summary":"Her fifth album blends pop, bossa nova, funk, rock and electronic music and hit 4.1 million streams in 24 hours.","body":["Luísa Sonza released her fifth studio album, “Brutal Paraíso”, on April 7. It runs 23 tracks and over an hour, arranged in three sections moving from introspection to sensuality and drama.","Singles “Telefone” and “Fruto do Tempo” came first, and the album features Xamã, Young Miko, Sebastián Yatra, MC Morena, MC Meno K and MC Paiva.","It logged 4.1 million Spotify streams in its first 24 hours and placed 13 songs on Brazil’s daily Top 200. Critics praised the ambition, though some felt it ran too long."]},"es":{"slug":"luisa-sonza-lanza-brutal-paraiso-quinto-album","headline":"Luísa Sonza lanza “Brutal Paraíso”, un álbum de 23 canciones con Young Miko y Sebastián Yatra","summary":"Su quinto disco mezcla pop, bossa nova, funk, rock y electrónica, y sumó 4,1 millones de streams en 24 horas.","body":["Luísa Sonza lanzó el 7 de abril “Brutal Paraíso”, su quinto álbum de estudio. Son 23 canciones y más de una hora de música, en tres bloques que van de la introspección a la sensualidad y el drama.","Lo precedieron los sencillos “Telefone” y “Fruto do Tempo”, y cuenta con Xamã, Young Miko, Sebastián Yatra, MC Morena, MC Meno K y MC Paiva.","En sus primeras 24 horas sumó 4,1 millones de streams en Spotify y colocó 13 canciones en el Top 200 diario de Brasil. La crítica elogió la ambición, aunque parte señaló que es demasiado largo."]}}}'::jsonb),
('article', '2029', 'published', '{"id":"2029","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-03-29T13:00:00Z","hue":275,"personIds":["bts"],"sources":[{"name":"Wikipedia — Arirang","url":"https://en.wikipedia.org/wiki/Arirang_(album)"},{"name":"Rolling Stone","url":"https://www.rollingstone.com/music/music-news/bts-arirang-first-week-sales-record-1235538129/"}],"t":{"pt":{"slug":"bts-arirang-recordes-primeira-semana-swim","headline":"BTS volta com “Arirang” e quebra recordes: 1º na Billboard 200 e “Swim” no topo da Hot 100","summary":"O álbum da volta do grupo vendeu 641 mil unidades nos EUA na estreia e 4,2 milhões de cópias na Coreia.","body":["O BTS lançou “Arirang” em 20 de março, primeiro álbum do grupo completo após o serviço militar. O disco estreou em 1º na Billboard 200 com 641 mil unidades nos EUA, a maior semana de um grupo desde 2014, e vendeu 4,2 milhões de cópias na Coreia do Sul.","O single “Swim” estreou no topo da Hot 100, e as 14 faixas ocuparam as 14 primeiras posições do ranking global do Spotify. O álbum abriu a “Arirang World Tour”, com 85 datas até março de 2027 — incluindo três shows em São Paulo."]},"en":{"slug":"bts-arirang-first-week-records-swim","headline":"BTS return with “Arirang” and break records: No. 1 on the Billboard 200 and “Swim” tops the Hot 100","summary":"The comeback album moved 641,000 U.S. units in week one and 4.2 million copies in Korea.","body":["BTS released “Arirang” on March 20, the group’s first album as a full lineup since military service. It debuted at No. 1 on the Billboard 200 with 641,000 U.S. units, the biggest week for a group since 2014, and sold 4.2 million copies in South Korea.","Lead single “Swim” debuted at No. 1 on the Hot 100, and all 14 tracks filled the top 14 of Spotify’s global chart. The album launched the Arirang World Tour, 85 dates through March 2027 — including three shows in São Paulo."]},"es":{"slug":"bts-arirang-records-primera-semana-swim","headline":"BTS vuelve con “Arirang” y rompe récords: #1 en el Billboard 200 y “Swim” en la cima del Hot 100","summary":"El álbum del regreso vendió 641 mil unidades en EE. UU. en su debut y 4,2 millones de copias en Corea.","body":["BTS lanzó “Arirang” el 20 de marzo, su primer álbum con el grupo completo tras el servicio militar. Debutó en el #1 del Billboard 200 con 641 mil unidades en EE. UU., la mayor semana de un grupo desde 2014, y vendió 4,2 millones de copias en Corea del Sur.","El sencillo “Swim” debutó en el #1 del Hot 100, y las 14 canciones ocuparon los 14 primeros puestos de la lista global de Spotify. El álbum abrió la Arirang World Tour, con 85 fechas hasta marzo de 2027, incluidas tres en São Paulo."]}}}'::jsonb),
('article', '2023', 'published', '{"id":"2023","section":"events","confidence":"confirmed","risk":"green","publishedAt":"2026-03-23T12:00:00Z","hue":120,"personIds":["sabrina-carpenter","luisa-sonza","chappell-roan","addison-rae"],"sources":[{"name":"Terra","url":"https://www.terra.com.br/diversao/musica/lollapalooza/quais-foram-os-melhores-e-piores-shows-do-lollapalooza-2026-veja-balanco-do-festival,5d4917ccbef8e702b8d9429e521caab5dp594c6z.html"}],"t":{"pt":{"slug":"lollapalooza-brasil-2026-balanco-sabrina-carpenter-luisa-sonza","headline":"Lollapalooza Brasil 2026: Sabrina Carpenter chama Luísa Sonza, Tyler, the Creator e Lorde brilham","summary":"O festival em Interlagos (20 a 22/3) teve Sabrina, Chappell Roan, Tyler e Lorde como atrações principais.","body":["O Lollapalooza Brasil 2026 aconteceu de 20 a 22 de março no Autódromo de Interlagos, com Sabrina Carpenter, Chappell Roan, Tyler, the Creator e Lorde no topo do line-up.","Sabrina fez um show completo e divertido e levou Luísa Sonza ao palco, apesar de problemas de volume. Na avaliação do Terra, Tyler, the Creator e Lorde fizeram algumas das melhores apresentações, e Negra Li abriu a sexta com uma aula de rap.","Do lado negativo, a crítica apontou o uso excessivo de playback nos shows de Addison Rae e Katseye. Os dias foram sem chuva, mas com lama no gramado."]},"en":{"slug":"lollapalooza-brasil-2026-recap-sabrina-carpenter-luisa-sonza","headline":"Lollapalooza Brasil 2026: Sabrina Carpenter brings out Luísa Sonza as Tyler, the Creator and Lorde shine","summary":"The Interlagos festival (March 20–22) was headlined by Sabrina, Chappell Roan, Tyler and Lorde.","body":["Lollapalooza Brasil 2026 ran March 20–22 at the Interlagos racetrack, headlined by Sabrina Carpenter, Chappell Roan, Tyler, the Creator and Lorde.","Sabrina delivered a fun, complete set and brought out Luísa Sonza despite some volume issues. Per Terra’s review, Tyler, the Creator and Lorde gave some of the best performances, and Negra Li opened Friday with a rap masterclass.","On the downside, critics flagged heavy playback in the sets by Addison Rae and Katseye. The days stayed dry, though the grounds were muddy."]},"es":{"slug":"lollapalooza-brasil-2026-balance-sabrina-carpenter-luisa-sonza","headline":"Lollapalooza Brasil 2026: Sabrina Carpenter invita a Luísa Sonza y brillan Tyler, the Creator y Lorde","summary":"El festival en Interlagos (20 al 22/3) tuvo a Sabrina, Chappell Roan, Tyler y Lorde como cabezas de cartel.","body":["Lollapalooza Brasil 2026 se celebró del 20 al 22 de marzo en el Autódromo de Interlagos, con Sabrina Carpenter, Chappell Roan, Tyler, the Creator y Lorde como cabezas de cartel.","Sabrina hizo un show completo y divertido e invitó a Luísa Sonza, pese a problemas de volumen. Según Terra, Tyler, the Creator y Lorde dieron algunas de las mejores presentaciones, y Negra Li abrió el viernes con una clase de rap.","En lo negativo, la crítica señaló el exceso de playback en los shows de Addison Rae y Katseye. No llovió, aunque el terreno estaba embarrado."]}}}'::jsonb),
('article', '2026', 'published', '{"id":"2026","section":"movies-tv","confidence":"confirmed","risk":"green","publishedAt":"2026-03-16T04:00:00Z","hue":200,"personIds":["wagner-moura","michael-b-jordan"],"sources":[{"name":"Billboard Brasil","url":"https://billboard.com.br/oscar-2026-lista-vencedores/"},{"name":"Omelete","url":"https://www.omelete.com.br/oscar-2026/oscar-2026-indicados"}],"t":{"pt":{"slug":"oscar-2026-uma-batalha-apos-a-outra-wagner-moura","headline":"Oscar 2026: “Uma Batalha Após a Outra” vence Melhor Filme; Wagner Moura disputou Melhor Ator","summary":"O filme de Paul Thomas Anderson levou seis estatuetas; “O Agente Secreto”, de Kleber Mendonça Filho, teve três indicações.","body":["O Oscar 2026, em 15 de março, consagrou “Uma Batalha Após a Outra”, de Paul Thomas Anderson, com seis prêmios, entre eles Melhor Filme, Direção e Ator Coadjuvante para Sean Penn.","Michael B. Jordan venceu Melhor Ator por “Pecadores”, Jessie Buckley levou Melhor Atriz por “Hamnet” e Amy Madigan ganhou como coadjuvante. “Valor Sentimental” foi o Melhor Filme Internacional.","O Brasil esteve na disputa com “O Agente Secreto”, de Kleber Mendonça Filho, indicado a Melhor Filme e Filme Internacional, e com Wagner Moura concorrendo a Melhor Ator."]},"en":{"slug":"oscars-2026-one-battle-after-another-wagner-moura","headline":"Oscars 2026: “One Battle After Another” wins Best Picture; Wagner Moura was up for Best Actor","summary":"Paul Thomas Anderson’s film took six awards; Kleber Mendonça Filho’s “The Secret Agent” earned three nominations.","body":["The March 15 Oscars crowned Paul Thomas Anderson’s “One Battle After Another” with six awards, including Best Picture, Director and Supporting Actor for Sean Penn.","Michael B. Jordan won Best Actor for “Sinners”, Jessie Buckley took Best Actress for “Hamnet” and Amy Madigan won Supporting Actress. “Sentimental Value” was Best International Feature.","Brazil competed with Kleber Mendonça Filho’s “The Secret Agent”, nominated for Best Picture and International Feature, and Wagner Moura in the Best Actor race."]},"es":{"slug":"oscar-2026-una-batalla-tras-otra-wagner-moura","headline":"Óscar 2026: “Una batalla tras otra” gana Mejor Película; Wagner Moura compitió como Mejor Actor","summary":"La película de Paul Thomas Anderson ganó seis estatuillas; “El agente secreto”, de Kleber Mendonça Filho, tuvo tres nominaciones.","body":["El Óscar del 15 de marzo coronó a “Una batalla tras otra”, de Paul Thomas Anderson, con seis premios, entre ellos Mejor Película, Dirección y Actor de Reparto para Sean Penn.","Michael B. Jordan ganó Mejor Actor por “Pecadores”, Jessie Buckley se llevó Mejor Actriz por “Hamnet” y Amy Madigan ganó como actriz de reparto. “Valor sentimental” fue Mejor Película Internacional.","Brasil compitió con “El agente secreto”, de Kleber Mendonça Filho, nominada a Mejor Película y Película Internacional, y con Wagner Moura en la categoría de Mejor Actor."]}}}'::jsonb),
('article', '2025', 'published', '{"id":"2025","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-02-10T15:00:00Z","hue":5,"personIds":["bad-bunny","kendrick-lamar"],"sources":[{"name":"Forbes","url":"https://www.forbes.com/sites/maurybrown/2026/02/10/super-bowl-lx-viewership-second-highest-all-time-bad-bunny-has-1282m-viewers/"},{"name":"CNN Business","url":"https://www.cnn.com/2026/02/10/media/super-bowl-lx-ratings-bad-bunny-nbc"}],"t":{"pt":{"slug":"super-bowl-lx-bad-bunny-128-milhoes-audiencia","headline":"Show de Bad Bunny no Super Bowl LX tem 128,2 milhões de espectadores nos EUA","summary":"É a quarta maior audiência de um show do intervalo, atrás de Kendrick Lamar, Michael Jackson e Usher.","body":["O show do intervalo de Bad Bunny no Super Bowl LX, em 8 de fevereiro, teve média de 128,2 milhões de espectadores nos Estados Unidos.","A marca é a quarta maior da história, atrás de Kendrick Lamar (2025), Michael Jackson (1993) e Usher (2024). O jogo, vencido pelo Seattle Seahawks sobre o New England Patriots no Levi’s Stadium, foi o primeiro medido com a nova metodologia da Nielsen."]},"en":{"slug":"super-bowl-lx-bad-bunny-128-million-viewers","headline":"Bad Bunny’s Super Bowl LX halftime show draws 128.2 million U.S. viewers","summary":"It ranks as the fourth-most-watched halftime show, behind Kendrick Lamar, Michael Jackson and Usher.","body":["Bad Bunny’s Super Bowl LX halftime show on February 8 averaged 128.2 million U.S. viewers.","That is the fourth-biggest halftime audience ever, behind Kendrick Lamar (2025), Michael Jackson (1993) and Usher (2024). The game, won by the Seattle Seahawks over the New England Patriots at Levi’s Stadium, was the first measured with Nielsen’s new methodology."]},"es":{"slug":"super-bowl-lx-bad-bunny-128-millones-audiencia","headline":"El show de Bad Bunny en el Super Bowl LX reúne 128,2 millones de espectadores en EE. UU.","summary":"Es la cuarta mayor audiencia de un show de medio tiempo, detrás de Kendrick Lamar, Michael Jackson y Usher.","body":["El show de medio tiempo de Bad Bunny en el Super Bowl LX, el 8 de febrero, promedió 128,2 millones de espectadores en Estados Unidos.","Es la cuarta cifra más alta de la historia, detrás de Kendrick Lamar (2025), Michael Jackson (1993) y Usher (2024). El partido, ganado por los Seattle Seahawks ante los New England Patriots en el Levi’s Stadium, fue el primero medido con la nueva metodología de Nielsen."]}}}'::jsonb),
('article', '2024', 'published', '{"id":"2024","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-02-02T05:00:00Z","hue":350,"personIds":["bad-bunny","kendrick-lamar","sza","billie-eilish","olivia-dean","lady-gaga"],"sources":[{"name":"PBS News","url":"https://www.pbs.org/newshour/arts/bad-bunny-wins-album-of-the-year-at-the-2026-grammy-awards-making-history-for-a-spanish-language-album"},{"name":"NPR","url":"https://www.npr.org/2026/02/01/nx-s1-5693046/2026-grammy-awards-full-list-winners-nominees"}],"t":{"pt":{"slug":"grammy-2026-bad-bunny-album-do-ano-historia","headline":"Grammy 2026: Bad Bunny faz história com o primeiro Álbum do Ano em espanhol","summary":"“Debí Tirar Más Fotos” levou o prêmio principal; Kendrick Lamar e SZA venceram Gravação do Ano e Olivia Dean foi a revelação.","body":["Bad Bunny venceu Álbum do Ano no Grammy 2026, em 1º de fevereiro, com “Debí Tirar Más Fotos”. É a primeira vez que um disco cantado em espanhol leva a principal categoria da premiação.","Kendrick Lamar e SZA ganharam Gravação do Ano com “Luther”, e Kendrick chegou a 27 Grammys na carreira, passando Jay-Z. Billie Eilish levou Canção do Ano com “Wildflower”, Olivia Dean foi eleita Artista Revelação e Lady Gaga venceu Melhor Álbum Pop Vocal.","No discurso, Bad Bunny exaltou Porto Rico, e vários artistas usaram o palco para criticar a política de imigração dos EUA."]},"en":{"slug":"grammys-2026-bad-bunny-album-of-the-year-history","headline":"Grammys 2026: Bad Bunny makes history with the first Spanish-language Album of the Year","summary":"“Debí Tirar Más Fotos” took the top prize; Kendrick Lamar and SZA won Record of the Year and Olivia Dean was Best New Artist.","body":["Bad Bunny won Album of the Year at the February 1 Grammys for “Debí Tirar Más Fotos”, the first Spanish-language album to take the ceremony’s top category.","Kendrick Lamar and SZA won Record of the Year for “Luther”, bringing Kendrick to 27 career Grammys and past Jay-Z. Billie Eilish won Song of the Year for “Wildflower”, Olivia Dean was named Best New Artist and Lady Gaga took Best Pop Vocal Album.","In his speech Bad Bunny celebrated Puerto Rico, and several artists used the stage to criticize U.S. immigration policy."]},"es":{"slug":"grammy-2026-bad-bunny-album-del-ano-historia","headline":"Grammy 2026: Bad Bunny hace historia con el primer Álbum del Año en español","summary":"“Debí Tirar Más Fotos” se llevó el premio mayor; Kendrick Lamar y SZA ganaron Grabación del Año y Olivia Dean fue la revelación.","body":["Bad Bunny ganó Álbum del Año en los Grammy del 1 de febrero con “Debí Tirar Más Fotos”, el primer disco en español que se lleva la categoría principal.","Kendrick Lamar y SZA ganaron Grabación del Año con “Luther”, y Kendrick llegó a 27 Grammy, superando a Jay-Z. Billie Eilish se llevó Canción del Año con “Wildflower”, Olivia Dean fue Mejor Artista Nuevo y Lady Gaga ganó Mejor Álbum Vocal Pop.","En su discurso, Bad Bunny celebró a Puerto Rico, y varios artistas usaron el escenario para criticar la política migratoria de EE. UU."]}}}'::jsonb),
('article', '2019', 'published', '{"id":"2019","section":"music","confidence":"confirmed","risk":"green","publishedAt":"2026-01-20T13:00:00Z","hue":55,"personIds":["luisa-sonza"],"sources":[{"name":"Billboard Brasil","url":"https://billboard.com.br/luisa-sonza-comenta-novo-album-2026/"}],"t":{"pt":{"slug":"luisa-sonza-bossa-sempre-nova-menescal-toquinho","headline":"Luísa Sonza mergulha na bossa nova em “Bossa Sempre Nova”, com Roberto Menescal e Toquinho","summary":"O projeto de janeiro reúne a cantora a dois nomes históricos do gênero e abriu o ano antes do álbum “Brutal Paraíso”.","body":["Luísa Sonza abriu 2026 com “Bossa Sempre Nova”, projeto dedicado à bossa nova com participações de Roberto Menescal e Toquinho.","O trabalho antecedeu o quinto álbum da cantora, “Brutal Paraíso”, lançado em abril, que manteve referências à bossa ao lado de funk, pop e eletrônico."]},"en":{"slug":"luisa-sonza-bossa-sempre-nova-menescal-toquinho","headline":"Luísa Sonza dives into bossa nova on “Bossa Sempre Nova” with Roberto Menescal and Toquinho","summary":"The January project pairs her with two legends of the genre and set up her April album “Brutal Paraíso”.","body":["Luísa Sonza opened 2026 with “Bossa Sempre Nova”, a bossa nova project featuring Roberto Menescal and Toquinho.","It came ahead of her fifth album, “Brutal Paraíso”, released in April, which kept bossa references alongside funk, pop and electronic music."]},"es":{"slug":"luisa-sonza-bossa-sempre-nova-menescal-toquinho","headline":"Luísa Sonza se sumerge en la bossa nova con “Bossa Sempre Nova”, junto a Roberto Menescal y Toquinho","summary":"El proyecto de enero la une a dos leyendas del género y abrió el camino a su álbum “Brutal Paraíso”.","body":["Luísa Sonza abrió 2026 con “Bossa Sempre Nova”, un proyecto de bossa nova con Roberto Menescal y Toquinho.","Llegó antes de su quinto álbum, “Brutal Paraíso”, lanzado en abril, que mantuvo referencias a la bossa junto al funk, el pop y la electrónica."]}}}'::jsonb),
('person', 'taylor-swift', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"taylorswift"}},"slug":"taylor-swift","publicName":"Taylor Swift","market":"global","kinds":["singer"],"country":"US","legalName":"Taylor Alison Swift","birthDate":"1989-12-13","birthPlace":"West Reading, Pensilvânia","activeSince":2004,"genres":["Pop","Country","Folk"],"works":[{"title":"Fearless","year":2008,"kind":"album"},{"title":"1989","year":2014,"kind":"album"},{"title":"Folklore","year":2020,"kind":"album"},{"title":"Midnights","year":2022,"kind":"album"},{"title":"The Eras Tour","year":2023,"kind":"tour"},{"title":"The Tortured Poets Department","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora e compositora","bio":"Cantora e compositora americana que começou no country e se tornou um dos maiores nomes do pop mundial. É conhecida pelas letras autobiográficas e por regravar os próprios álbuns nas “Taylor’s Versions”.","highlights":["The Eras Tour (2023–2024) se tornou a turnê de maior bilheteria da história.","É a recordista de vitórias em Álbum do Ano no Grammy, com quatro prêmios.","Recomprou em 2025 os masters dos seus seis primeiros álbuns."]},"en":{"role":"Singer-songwriter","bio":"American singer-songwriter who started in country and became one of the biggest names in global pop. She is known for autobiographical lyrics and for re-recording her own albums as “Taylor’s Versions”.","highlights":["The Eras Tour (2023–2024) became the highest-grossing tour of all time.","She holds the record for most Album of the Year wins at the Grammys, with four.","In 2025 she bought back the masters of her first six albums."]},"es":{"role":"Cantautora","bio":"Cantautora estadounidense que empezó en el country y se convirtió en uno de los mayores nombres del pop mundial. Es conocida por sus letras autobiográficas y por regrabar sus propios álbumes como “Taylor’s Versions”.","highlights":["The Eras Tour (2023–2024) se convirtió en la gira más taquillera de la historia.","Tiene el récord de premios a Álbum del Año en los Grammy, con cuatro.","En 2025 recompró los masters de sus seis primeros álbumes."]}},"id":"taylor-swift","hue":320}'::jsonb),
('person', 'beyonce', 'published', '{"aliases":["Beyonce","Queen B"],"socials":{"instagram":{"handle":"beyonce"}},"slug":"beyonce","publicName":"Beyoncé","market":"global","kinds":["singer"],"country":"US","legalName":"Beyoncé Giselle Knowles-Carter","birthDate":"1981-09-04","birthPlace":"Houston, Texas","activeSince":1990,"genres":["R&B","Pop","Hip-hop","Country"],"works":[{"title":"Dangerously in Love","year":2003,"kind":"album"},{"title":"Lemonade","year":2016,"kind":"album"},{"title":"Renaissance","year":2022,"kind":"album"},{"title":"Renaissance World Tour","year":2023,"kind":"tour"},{"title":"Cowboy Carter","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora, compositora e empresária","bio":"Cantora americana que ficou famosa no Destiny’s Child antes de seguir carreira solo. É uma das artistas mais influentes do pop e do R&B.","highlights":["É a artista com mais vitórias na história do Grammy.","Venceu Álbum do Ano no Grammy 2025 com “Cowboy Carter”.","“Lemonade” (2016) foi lançado junto com um filme visual."]},"en":{"role":"Singer, songwriter and businesswoman","bio":"American singer who rose to fame with Destiny’s Child before going solo. She is one of the most influential artists in pop and R&B.","highlights":["She is the most awarded artist in Grammy history.","She won Album of the Year at the 2025 Grammys with “Cowboy Carter”.","“Lemonade” (2016) was released alongside a visual film."]},"es":{"role":"Cantante, compositora y empresaria","bio":"Cantante estadounidense que saltó a la fama con Destiny’s Child antes de su carrera solista. Es una de las artistas más influyentes del pop y el R&B.","highlights":["Es la artista con más premios en la historia de los Grammy.","Ganó Álbum del Año en los Grammy 2025 con “Cowboy Carter”.","“Lemonade” (2016) se lanzó junto con una película visual."]}},"id":"beyonce","hue":7}'::jsonb),
('person', 'rihanna', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"badgalriri"}},"slug":"rihanna","publicName":"Rihanna","market":"global","kinds":["singer"],"country":"BB","legalName":"Robyn Rihanna Fenty","birthDate":"1988-02-20","birthPlace":"Saint Michael, Barbados","activeSince":2005,"genres":["Pop","R&B","Dancehall"],"works":[{"title":"Good Girl Gone Bad","year":2007,"kind":"album"},{"title":"Loud","year":2010,"kind":"album"},{"title":"Anti","year":2016,"kind":"album"},{"title":"Fenty Beauty","year":2017,"kind":"project"}],"t":{"pt":{"role":"Cantora e empresária","bio":"Cantora e empresária de Barbados, dona de uma das sequências de hits mais fortes do pop dos anos 2000 e 2010. Fundou a Fenty Beauty, marca que mudou o padrão de inclusão na indústria da beleza.","highlights":["“Umbrella” (2007) lhe deu projeção mundial.","Criou a Fenty Beauty (2017) e a Savage X Fenty (2018).","Fez o show do intervalo do Super Bowl LVII, em 2023."]},"en":{"role":"Singer and entrepreneur","bio":"Barbadian singer and entrepreneur behind one of the strongest hit runs in 2000s and 2010s pop. She founded Fenty Beauty, a brand that reset the standard for inclusion in the beauty industry.","highlights":["“Umbrella” (2007) made her a global star.","She founded Fenty Beauty (2017) and Savage X Fenty (2018).","She headlined the Super Bowl LVII halftime show in 2023."]},"es":{"role":"Cantante y empresaria","bio":"Cantante y empresaria de Barbados, con una de las rachas de éxitos más fuertes del pop de los 2000 y 2010. Fundó Fenty Beauty, una marca que cambió el estándar de inclusión en la industria de la belleza.","highlights":["“Umbrella” (2007) la convirtió en estrella mundial.","Creó Fenty Beauty (2017) y Savage X Fenty (2018).","Protagonizó el show de medio tiempo del Super Bowl LVII en 2023."]}},"id":"rihanna","hue":54}'::jsonb),
('person', 'justin-bieber', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"justinbieber"}},"slug":"justin-bieber","publicName":"Justin Bieber","market":"global","kinds":["singer"],"country":"CA","legalName":"Justin Drew Bieber","birthDate":"1994-03-01","birthPlace":"London, Ontário","activeSince":2008,"genres":["Pop","R&B"],"works":[{"title":"My World 2.0","year":2010,"kind":"album"},{"title":"Purpose","year":2015,"kind":"album"},{"title":"Justice","year":2021,"kind":"album"},{"title":"Swag","year":2025,"kind":"album"}],"t":{"pt":{"role":"Cantor","bio":"Cantor canadense descoberto no YouTube ainda adolescente, que virou um fenômeno global do pop. Nos trabalhos mais recentes aproximou o som do R&B.","highlights":["“Baby” (2010) foi um dos primeiros clipes a virar fenômeno no YouTube.","“Purpose” (2015) emplacou “Sorry”, “Love Yourself” e “What Do You Mean?”.","Lançou de surpresa o álbum “Swag” em 2025."]},"en":{"role":"Singer","bio":"Canadian singer discovered on YouTube as a teenager who became a global pop phenomenon. His recent work leans toward R&B.","highlights":["“Baby” (2010) was one of the first music videos to become a YouTube phenomenon.","“Purpose” (2015) delivered “Sorry”, “Love Yourself” and “What Do You Mean?”.","He surprise-released the album “Swag” in 2025."]},"es":{"role":"Cantante","bio":"Cantante canadiense descubierto en YouTube cuando era adolescente, que se convirtió en un fenómeno global del pop. Sus trabajos recientes se acercan al R&B.","highlights":["“Baby” (2010) fue uno de los primeros videos en volverse fenómeno en YouTube.","“Purpose” (2015) trajo “Sorry”, “Love Yourself” y “What Do You Mean?”.","Lanzó por sorpresa el álbum “Swag” en 2025."]}},"id":"justin-bieber","hue":101}'::jsonb),
('person', 'ariana-grande', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"arianagrande"}},"slug":"ariana-grande","publicName":"Ariana Grande","market":"global","kinds":["singer","actor"],"country":"US","legalName":"Ariana Grande-Butera","birthDate":"1993-06-26","birthPlace":"Boca Raton, Flórida","activeSince":2008,"genres":["Pop","R&B"],"works":[{"title":"My Everything","year":2014,"kind":"album"},{"title":"Sweetener","year":2018,"kind":"album"},{"title":"Thank U, Next","year":2019,"kind":"album"},{"title":"Eternal Sunshine","year":2024,"kind":"album"},{"title":"Wicked","year":2024,"kind":"film"}],"t":{"pt":{"role":"Cantora e atriz","bio":"Cantora e atriz americana conhecida pelo alcance vocal e por hits como “Thank U, Next” e “7 Rings”. Começou na TV, na série “Victorious”, e voltou às telas como Glinda em “Wicked”.","highlights":["Indicada ao Oscar de Melhor Atriz Coadjuvante por “Wicked” (2024).","Venceu o Grammy de Melhor Álbum Pop Vocal com “Sweetener”.","“Thank U, Next” (2019) quebrou recordes de streaming no lançamento."]},"en":{"role":"Singer and actress","bio":"American singer and actress known for her vocal range and hits like “Thank U, Next” and “7 Rings”. She started on TV in “Victorious” and returned to the screen as Glinda in “Wicked”.","highlights":["Nominated for the Oscar for Best Supporting Actress for “Wicked” (2024).","Won the Grammy for Best Pop Vocal Album with “Sweetener”.","“Thank U, Next” (2019) broke streaming records on release."]},"es":{"role":"Cantante y actriz","bio":"Cantante y actriz estadounidense conocida por su rango vocal y por éxitos como “Thank U, Next” y “7 Rings”. Empezó en la TV con “Victorious” y volvió a la pantalla como Glinda en “Wicked”.","highlights":["Nominada al Óscar a Mejor Actriz de Reparto por “Wicked” (2024).","Ganó el Grammy a Mejor Álbum Vocal Pop con “Sweetener”.","“Thank U, Next” (2019) rompió récords de streaming en su estreno."]}},"id":"ariana-grande","hue":148}'::jsonb),
('person', 'billie-eilish', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"billieeilish"}},"slug":"billie-eilish","publicName":"Billie Eilish","market":"global","kinds":["singer"],"country":"US","legalName":"Billie Eilish Pirate Baird O''Connell","birthDate":"2001-12-18","birthPlace":"Los Angeles, Califórnia","activeSince":2015,"genres":["Pop","Alternativo"],"works":[{"title":"When We All Fall Asleep, Where Do We Go?","year":2019,"kind":"album"},{"title":"Happier Than Ever","year":2021,"kind":"album"},{"title":"Hit Me Hard and Soft","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora e compositora","bio":"Cantora e compositora americana que estourou com “Ocean Eyes” e produz as músicas com o irmão, Finneas. Marcou uma geração com um pop sombrio e intimista.","highlights":["Venceu os quatro principais Grammys na mesma noite, em 2020.","Tem dois Oscars de Melhor Canção Original: “No Time to Die” e “What Was I Made For?”.","“Birds of a Feather” (2024) virou um dos maiores hits de sua carreira."]},"en":{"role":"Singer-songwriter","bio":"American singer-songwriter who broke through with “Ocean Eyes” and makes her music with her brother, Finneas. Her dark, intimate pop defined a generation.","highlights":["She won all four major Grammys in a single night in 2020.","She has two Oscars for Best Original Song: “No Time to Die” and “What Was I Made For?”.","“Birds of a Feather” (2024) became one of the biggest hits of her career."]},"es":{"role":"Cantautora","bio":"Cantautora estadounidense que despegó con “Ocean Eyes” y hace su música con su hermano, Finneas. Su pop oscuro e íntimo marcó a una generación.","highlights":["Ganó los cuatro Grammy principales en una misma noche, en 2020.","Tiene dos Óscar a Mejor Canción Original: “No Time to Die” y “What Was I Made For?”.","“Birds of a Feather” (2024) se volvió uno de los mayores éxitos de su carrera."]}},"id":"billie-eilish","hue":195}'::jsonb),
('person', 'the-weeknd', 'published', '{"aliases":["Abel Tesfaye"],"socials":{"instagram":{"handle":"theweeknd"}},"slug":"the-weeknd","publicName":"The Weeknd","market":"global","kinds":["singer"],"country":"CA","legalName":"Abel Makkonen Tesfaye","birthDate":"1990-02-16","birthPlace":"Toronto, Ontário","activeSince":2009,"genres":["R&B","Pop","Synth-pop"],"works":[{"title":"Beauty Behind the Madness","year":2015,"kind":"album"},{"title":"After Hours","year":2020,"kind":"album"},{"title":"Dawn FM","year":2022,"kind":"album"},{"title":"Hurry Up Tomorrow","year":2025,"kind":"album"}],"t":{"pt":{"role":"Cantor e produtor","bio":"Cantor e produtor canadense que saiu das mixtapes anônimas para o topo do pop, misturando R&B sombrio com sintetizadores dos anos 80.","highlights":["“Blinding Lights” é uma das músicas mais tocadas da história do Spotify.","Fez o show do intervalo do Super Bowl LV, em 2021.","Fechou com “Hurry Up Tomorrow” (2025) a trilogia iniciada em “After Hours”."]},"en":{"role":"Singer and producer","bio":"Canadian singer and producer who went from anonymous mixtapes to the top of pop, blending dark R&B with ’80s synths.","highlights":["“Blinding Lights” is one of the most-streamed songs in Spotify history.","He headlined the Super Bowl LV halftime show in 2021.","“Hurry Up Tomorrow” (2025) closed the trilogy that began with “After Hours”."]},"es":{"role":"Cantante y productor","bio":"Cantante y productor canadiense que pasó de mixtapes anónimos a la cima del pop, mezclando R&B oscuro con sintetizadores ochenteros.","highlights":["“Blinding Lights” es una de las canciones más escuchadas en la historia de Spotify.","Protagonizó el show de medio tiempo del Super Bowl LV en 2021.","“Hurry Up Tomorrow” (2025) cerró la trilogía iniciada con “After Hours”."]}},"id":"the-weeknd","hue":242}'::jsonb),
('person', 'drake', 'published', '{"aliases":["Aubrey Graham"],"socials":{"instagram":{"handle":"champagnepapi"}},"slug":"drake","publicName":"Drake","market":"global","kinds":["singer"],"country":"CA","legalName":"Aubrey Drake Graham","birthDate":"1986-10-24","birthPlace":"Toronto, Ontário","activeSince":2001,"genres":["Hip-hop","R&B"],"works":[{"title":"Take Care","year":2011,"kind":"album"},{"title":"Nothing Was the Same","year":2013,"kind":"album"},{"title":"Views","year":2016,"kind":"album"},{"title":"Scorpion","year":2018,"kind":"album"}],"t":{"pt":{"role":"Rapper e cantor","bio":"Rapper, cantor e empresário canadense que começou como ator na série “Degrassi”. É um dos artistas mais ouvidos da era do streaming.","highlights":["“Take Care” venceu o Grammy de Melhor Álbum de Rap.","“One Dance” e “God’s Plan” estão entre os maiores hits de streaming da sua geração.","Fundou o selo e a marca OVO."]},"en":{"role":"Rapper and singer","bio":"Canadian rapper, singer and entrepreneur who started as an actor on “Degrassi”. He is one of the most-streamed artists of the streaming era.","highlights":["“Take Care” won the Grammy for Best Rap Album.","“One Dance” and “God’s Plan” are among the biggest streaming hits of his generation.","He founded the OVO label and brand."]},"es":{"role":"Rapero y cantante","bio":"Rapero, cantante y empresario canadiense que empezó como actor en la serie “Degrassi”. Es uno de los artistas más escuchados de la era del streaming.","highlights":["“Take Care” ganó el Grammy a Mejor Álbum de Rap.","“One Dance” y “God’s Plan” están entre los mayores éxitos de streaming de su generación.","Fundó el sello y la marca OVO."]}},"id":"drake","hue":289}'::jsonb),
('person', 'dua-lipa', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"dualipa"}},"slug":"dua-lipa","publicName":"Dua Lipa","market":"global","kinds":["singer"],"country":"GB","birthDate":"1995-08-22","birthPlace":"Londres, Inglaterra","activeSince":2014,"genres":["Pop","Dance"],"works":[{"title":"Dua Lipa","year":2017,"kind":"album"},{"title":"Future Nostalgia","year":2020,"kind":"album"},{"title":"Dance the Night","year":2023,"kind":"single"},{"title":"Radical Optimism","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora e compositora","bio":"Cantora britânica de família kosovar-albanesa, referência do pop dançante desde “Future Nostalgia”. Também apresenta o podcast “At Your Service”.","highlights":["“Future Nostalgia” venceu o Grammy de Melhor Álbum Pop Vocal.","“Levitating” foi uma das músicas mais tocadas de 2021.","Gravou “Dance the Night” para a trilha de “Barbie” (2023)."]},"en":{"role":"Singer-songwriter","bio":"British singer of Kosovo-Albanian descent and a reference for dance-pop since “Future Nostalgia”. She also hosts the podcast “At Your Service”.","highlights":["“Future Nostalgia” won the Grammy for Best Pop Vocal Album.","“Levitating” was one of the most-played songs of 2021.","She recorded “Dance the Night” for the “Barbie” soundtrack (2023)."]},"es":{"role":"Cantautora","bio":"Cantante británica de familia kosovar-albanesa, referente del pop bailable desde “Future Nostalgia”. También conduce el podcast “At Your Service”.","highlights":["“Future Nostalgia” ganó el Grammy a Mejor Álbum Vocal Pop.","“Levitating” fue una de las canciones más sonadas de 2021.","Grabó “Dance the Night” para la banda sonora de “Barbie” (2023)."]}},"id":"dua-lipa","hue":336}'::jsonb),
('person', 'sabrina-carpenter', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"sabrinacarpenter"}},"slug":"sabrina-carpenter","publicName":"Sabrina Carpenter","market":"global","kinds":["singer","actor"],"country":"US","legalName":"Sabrina Annlynn Carpenter","birthDate":"1999-05-11","birthPlace":"Quakertown, Pensilvânia","activeSince":2011,"genres":["Pop"],"works":[{"title":"Emails I Can''t Send","year":2022,"kind":"album"},{"title":"Espresso","year":2024,"kind":"single"},{"title":"Short n'' Sweet","year":2024,"kind":"album"},{"title":"Man''s Best Friend","year":2025,"kind":"album"}],"t":{"pt":{"role":"Cantora e atriz","bio":"Cantora e atriz americana que começou na Disney, na série “Girl Meets World”, e virou estrela pop global com “Espresso” e “Please Please Please”.","highlights":["“Short n’ Sweet” venceu o Grammy de Melhor Álbum Pop Vocal em 2025.","“Espresso” foi um dos maiores hits de 2024.","Lançou “Man’s Best Friend” em 2025."]},"en":{"role":"Singer and actress","bio":"American singer and actress who started at Disney on “Girl Meets World” and became a global pop star with “Espresso” and “Please Please Please”.","highlights":["“Short n’ Sweet” won the Grammy for Best Pop Vocal Album in 2025.","“Espresso” was one of the biggest hits of 2024.","She released “Man’s Best Friend” in 2025."]},"es":{"role":"Cantante y actriz","bio":"Cantante y actriz estadounidense que empezó en Disney con “Girl Meets World” y se volvió estrella pop global con “Espresso” y “Please Please Please”.","highlights":["“Short n’ Sweet” ganó el Grammy a Mejor Álbum Vocal Pop en 2025.","“Espresso” fue uno de los mayores éxitos de 2024.","Lanzó “Man’s Best Friend” en 2025."]}},"id":"sabrina-carpenter","hue":23}'::jsonb),
('person', 'bad-bunny', 'published', '{"aliases":["Benito"],"socials":{"instagram":{"handle":"badbunnypr"}},"slug":"bad-bunny","publicName":"Bad Bunny","market":"latin","kinds":["singer"],"country":"PR","legalName":"Benito Antonio Martínez Ocasio","birthDate":"1994-03-10","birthPlace":"Bayamón, Porto Rico","activeSince":2013,"genres":["Reggaeton","Trap latino"],"works":[{"title":"YHLQMDLG","year":2020,"kind":"album"},{"title":"Un Verano Sin Ti","year":2022,"kind":"album"},{"title":"Nadie Sabe Lo Que Va a Pasar Mañana","year":2023,"kind":"album"},{"title":"Debí Tirar Más Fotos","year":2025,"kind":"album"}],"t":{"pt":{"role":"Rapper e cantor","bio":"Rapper e cantor porto-riquenho que levou a música em espanhol ao topo das paradas mundiais sem abrir mão do idioma nem das raízes caribenhas.","highlights":["Foi o artista mais ouvido do mundo no Spotify em 2020, 2021 e 2022.","“Un Verano Sin Ti” foi o primeiro álbum todo em espanhol indicado a Álbum do Ano no Grammy.","Foi a atração do show do intervalo do Super Bowl LX, em 2026."]},"en":{"role":"Rapper and singer","bio":"Puerto Rican rapper and singer who took Spanish-language music to the top of the global charts without giving up his language or Caribbean roots.","highlights":["He was Spotify’s most-streamed artist worldwide in 2020, 2021 and 2022.","“Un Verano Sin Ti” was the first all-Spanish album nominated for Album of the Year at the Grammys.","He headlined the Super Bowl LX halftime show in 2026."]},"es":{"role":"Rapero y cantante","bio":"Rapero y cantante puertorriqueño que llevó la música en español a la cima de las listas mundiales sin renunciar a su idioma ni a sus raíces caribeñas.","highlights":["Fue el artista más escuchado del mundo en Spotify en 2020, 2021 y 2022.","“Un Verano Sin Ti” fue el primer álbum totalmente en español nominado a Álbum del Año en los Grammy.","Protagonizó el show de medio tiempo del Super Bowl LX en 2026."]}},"id":"bad-bunny","hue":70}'::jsonb),
('person', 'shakira', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"shakira"}},"slug":"shakira","publicName":"Shakira","market":"latin","kinds":["singer"],"country":"CO","legalName":"Shakira Isabel Mebarak Ripoll","birthDate":"1977-02-02","birthPlace":"Barranquilla, Colômbia","activeSince":1990,"genres":["Pop latino","Rock","Dance"],"works":[{"title":"Pies Descalzos","year":1995,"kind":"album"},{"title":"Laundry Service","year":2001,"kind":"album"},{"title":"Waka Waka","year":2010,"kind":"single"},{"title":"Las Mujeres Ya No Lloran","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora e compositora","bio":"Cantora e compositora colombiana, pioneira do crossover latino no pop mundial, de “Hips Don’t Lie” a “Waka Waka”.","highlights":["“Waka Waka” foi o hino da Copa do Mundo de 2010.","Dividiu o show do intervalo do Super Bowl LIV (2020) com Jennifer Lopez.","“Las Mujeres Ya No Lloran” venceu o Grammy de Melhor Álbum Pop Latino."]},"en":{"role":"Singer-songwriter","bio":"Colombian singer-songwriter and a pioneer of the Latin crossover into global pop, from “Hips Don’t Lie” to “Waka Waka”.","highlights":["“Waka Waka” was the anthem of the 2010 World Cup.","She co-headlined the Super Bowl LIV halftime show (2020) with Jennifer Lopez.","“Las Mujeres Ya No Lloran” won the Grammy for Best Latin Pop Album."]},"es":{"role":"Cantautora","bio":"Cantautora colombiana, pionera del crossover latino en el pop mundial, de “Hips Don’t Lie” a “Waka Waka”.","highlights":["“Waka Waka” fue el himno del Mundial de 2010.","Compartió el show de medio tiempo del Super Bowl LIV (2020) con Jennifer Lopez.","“Las Mujeres Ya No Lloran” ganó el Grammy a Mejor Álbum de Pop Latino."]}},"id":"shakira","hue":117}'::jsonb),
('person', 'karol-g', 'published', '{"aliases":["La Bichota"],"socials":{"instagram":{"handle":"karolg"}},"slug":"karol-g","publicName":"Karol G","market":"latin","kinds":["singer"],"country":"CO","legalName":"Carolina Giraldo Navarro","birthDate":"1991-02-14","birthPlace":"Medellín, Colômbia","activeSince":2006,"genres":["Reggaeton","Pop latino"],"works":[{"title":"KG0516","year":2021,"kind":"album"},{"title":"Mañana Será Bonito","year":2023,"kind":"album"},{"title":"Tropicoqueta","year":2025,"kind":"album"}],"t":{"pt":{"role":"Cantora","bio":"Cantora colombiana de reggaeton conhecida como “La Bichota”, uma das artistas latinas de maior sucesso da década.","highlights":["“Mañana Será Bonito” foi o primeiro álbum em espanhol de uma mulher a estrear em 1º na Billboard 200.","O mesmo disco venceu o Grammy de Melhor Álbum de Música Urbana.","“Tusa”, com Nicki Minaj, virou um clássico do reggaeton."]},"en":{"role":"Singer","bio":"Colombian reggaeton singer known as “La Bichota” and one of the most successful Latin artists of the decade.","highlights":["“Mañana Será Bonito” was the first Spanish-language album by a woman to debut at No. 1 on the Billboard 200.","The same record won the Grammy for Best Música Urbana Album.","“Tusa”, with Nicki Minaj, became a reggaeton classic."]},"es":{"role":"Cantante","bio":"Cantante colombiana de reguetón conocida como “La Bichota”, una de las artistas latinas más exitosas de la década.","highlights":["“Mañana Será Bonito” fue el primer álbum en español de una mujer en debutar en el #1 del Billboard 200.","Ese mismo disco ganó el Grammy a Mejor Álbum de Música Urbana.","“Tusa”, con Nicki Minaj, se volvió un clásico del reguetón."]}},"id":"karol-g","hue":164}'::jsonb),
