('person', 'bizarrap', 'published', '{"aliases":["Biza","BZRP"],"socials":{},"slug":"bizarrap","publicName":"Bizarrap","market":"latin","kinds":["singer"],"country":"AR","legalName":"Gonzalo Julián Conde","birthDate":"1998-08-29","birthPlace":"Ramos Mejía, Argentina","activeSince":2017,"genres":["Eletrônica","Trap","Hip-hop"],"works":[{"title":"BZRP Music Sessions","year":2019,"kind":"project"},{"title":"Session #52 (Quevedo)","year":2022,"kind":"single"},{"title":"Session #53 (Shakira)","year":2023,"kind":"single"}],"t":{"pt":{"role":"Produtor e DJ","bio":"Produtor e DJ argentino que ficou famoso pelas “BZRP Music Sessions”, parcerias gravadas com artistas do mundo todo.","highlights":["A Session #53, com Shakira, bateu recordes de visualização no YouTube em 2023.","A Session #52, com Quevedo, virou hit global em 2022.","Aparece sempre de boné e óculos escuros, sem mostrar o rosto por inteiro."]},"en":{"role":"Producer and DJ","bio":"Argentine producer and DJ famous for the “BZRP Music Sessions”, collaborations recorded with artists from around the world.","highlights":["Session #53, with Shakira, broke YouTube viewing records in 2023.","Session #52, with Quevedo, became a global hit in 2022.","He always appears in a cap and sunglasses, never fully showing his face."]},"es":{"role":"Productor y DJ","bio":"Productor y DJ argentino famoso por las “BZRP Music Sessions”, colaboraciones grabadas con artistas de todo el mundo.","highlights":["La Session #53, con Shakira, rompió récords de reproducciones en YouTube en 2023.","La Session #52, con Quevedo, fue un éxito global en 2022.","Siempre aparece con gorra y lentes oscuros, sin mostrar el rostro por completo."]}},"id":"bizarrap","hue":133}'::jsonb),
('person', 'anitta', 'published', '{"aliases":[],"socials":{"instagram":{"handle":"anitta"}},"slug":"anitta","publicName":"Anitta","market":"brazil","kinds":["singer"],"country":"BR","legalName":"Larissa de Macedo Machado","birthDate":"1993-03-30","birthPlace":"Rio de Janeiro, RJ","activeSince":2011,"genres":["Pop","Funk","Reggaeton"],"works":[{"title":"Show das Poderosas","year":2013,"kind":"single"},{"title":"Kisses","year":2019,"kind":"album"},{"title":"Versions of Me","year":2022,"kind":"album"},{"title":"Funk Generation","year":2024,"kind":"album"}],"t":{"pt":{"role":"Cantora, compositora e empresária","bio":"Cantora e empresária carioca que levou o funk brasileiro ao mercado internacional e é a artista brasileira de maior alcance global.","highlights":["“Envolver” (2022) foi a primeira música de uma artista brasileira solo a chegar ao 1º lugar global do Spotify.","Primeira artista brasileira a ganhar um VMA, com “Envolver”.","“Funk Generation” (2024) foi indicado ao Grammy de Melhor Álbum de Música Urbana."]},"en":{"role":"Singer, songwriter and businesswoman","bio":"Rio de Janeiro singer and businesswoman who took Brazilian funk to the international market and is Brazil’s artist with the widest global reach.","highlights":["“Envolver” (2022) was the first song by a solo Brazilian artist to hit No. 1 on Spotify’s global chart.","She was the first Brazilian artist to win a VMA, with “Envolver”.","“Funk Generation” (2024) was nominated for the Grammy for Best Música Urbana Album."]},"es":{"role":"Cantante, compositora y empresaria","bio":"Cantante y empresaria de Río de Janeiro que llevó el funk brasileño al mercado internacional y es la artista brasileña de mayor alcance global.","highlights":["“Envolver” (2022) fue la primera canción de una artista brasileña solista en llegar al #1 global de Spotify.","Fue la primera artista brasileña en ganar un VMA, con “Envolver”.","“Funk Generation” (2024) fue nominado al Grammy a Mejor Álbum de Música Urbana."]}},"id":"anitta","hue":180}'::jsonb),
