('person', 'ivete-sangalo', 'published', '{"aliases":["Veveta"],"socials":{"instagram":{"handle":"ivetesangalo"}},"slug":"ivete-sangalo","publicName":"Ivete Sangalo","market":"brazil","kinds":["singer"],"country":"BR","legalName":"Ivete Maria Dias de Sangalo","birthDate":"1972-05-27","birthPlace":"Juazeiro, BA","activeSince":1993,"genres":["Axé","MPB","Pop"],"works":[{"title":"Banda Eva","year":1993,"kind":"project"},{"title":"MTV ao Vivo","year":2004,"kind":"album"},{"title":"Multishow ao Vivo no Maracanã","year":2007,"kind":"album"}],"t":{"pt":{"role":"Cantora e apresentadora","bio":"Cantora, compositora e apresentadora baiana, maior nome do axé e presença constante no Carnaval de Salvador desde os anos 1990.","highlights":["Ficou conhecida como vocalista da Banda Eva antes da carreira solo, iniciada em 1999.","“MTV ao Vivo” (2004) é um dos DVDs mais vendidos da história do Brasil.","Gravou no Maracanã um show histórico, lançado em 2007."]},"en":{"role":"Singer and TV host","bio":"Singer, songwriter and TV host from Bahia, the biggest name in axé music and a fixture of Salvador’s Carnival since the 1990s.","highlights":["She rose to fame as lead singer of Banda Eva before going solo in 1999.","“MTV ao Vivo” (2004) is one of the best-selling DVDs in Brazilian history.","She recorded a landmark concert at Maracanã, released in 2007."]},"es":{"role":"Cantante y presentadora","bio":"Cantante, compositora y presentadora de Bahía, el mayor nombre del axé y figura habitual del Carnaval de Salvador desde los años 90.","highlights":["Se hizo conocida como vocalista de Banda Eva antes de su carrera solista, iniciada en 1999.","“MTV ao Vivo” (2004) es uno de los DVD más vendidos de la historia de Brasil.","Grabó en el Maracaná un concierto histórico, lanzado en 2007."]}},"id":"ivete-sangalo","hue":321}'::jsonb),
